const KEI=[{"id": "daikon", "kind": "yasai", "name": "大根", "yomi": "だいこん", "en": "Daikon radish", "rep": "daikon_a2.jpg", "lead": "名の由来は「大きな根」。古事記の歌にあらわれ、七草に数えられ、軒先に干されてきた、日本の台所にいちばん近い白。", "layers": [["白いところの正体", "アブラナ科ダイコン属の野菜。食べている白い部分は一本まるごと根ではなく、上半分は茎の付け根（胚軸）、下半分が根とされる。ひげ根の跡が縦に並ぶのは根の部分だけで、春には菜の花に似た十字の花を咲かせる。"], ["来歴", "原産は地中海沿岸から中央アジアにかけてとされ、日本へは弥生時代ごろに渡来したと考えられている。古事記の仁徳天皇の歌に「おほね」として現れ、春の七草では「すずしろ」の名で数えられる。江戸時代に品種が一気に増え、練馬・聖護院・桜島など、土地の名を背負った大根が各地に育った。"], ["文化", "煮て、おろして、漬けて、干して——ひとつの野菜でこれほど食べ方の動詞が多いものは少ない。冬に軒先へ吊るす大根干しは、いまも各地に残る風物詩。芝居のへたな役者を「大根役者」と呼ぶ言い回しには、あたらない（食あたりしない）からなど、由来に諸説あるとされる。"]], "invite": "台所の大根の表面で、ひげ根の跡を探してみる。跡が縦に並ぶ下半分が根、つるりとした上半分は茎の付け根——一本の中に境目がある。", "works": [{"t": "bun", "date": "1688年（貞享5）", "place": "日本", "title": "更科紀行", "author": "松尾芭蕉", "quote": "身にしみて大根からし秋の風", "src": "『更科紀行』（貞享5年・1688の木曽路〜更科の旅）。本文は「芭蕉俳句全集」（Wikisource）で照合", "note": "木曽路から更科へ月を見にゆく旅の句。大根おろしの辛さと、身にしみる秋風のつめたさをひとつに重ねた。表記は「身に沁みて」とも書かれる。"}, {"t": "bun", "date": "1814年（文化11）", "place": "日本", "title": "七番日記", "author": "小林一茶", "quote": "大根引大根で道を教へけり", "src": "『七番日記』（文化11年・1814）。今日では「大根引き大根で道を教えけり」の表記でも知られる", "note": "大根を引く農夫が、道を訊かれて、抜いたばかりの大根で方角を指してみせた。土の湯気まで見えるような、暮らしの言葉で詠む一茶調の句。"}, {"t": "art", "f": "daikon_a1.jpg", "date": "1820年ごろ（江戸）", "place": "日本", "title": "大根に菊とシダ（A Giant Radish, Chrysanthemums, and Ferns）", "artist": "柳々居辰斎", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/23525", "note": "狂歌が添えられた摺物（すりもの）で、歌仲間が私的に配った贅沢な刷り物とされる。白い大根が菊やシダと同格で画面に招かれ、淡い絵具が金属質に光る。辰斎は北斎に学んだ絵師とされる。"}, {"t": "art", "f": "daikon_a2.jpg", "date": "1840年代（江戸）", "place": "日本", "title": "ねずみと大根（Mice and radish）", "artist": "歌川広重", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/56206", "note": "藍の濃淡だけで刷った中判に、大きな大根と二匹のネズミ。ネズミは大黒天の使いとされ、大黒天には二股の大根を供える風習もあった——実りと福を呼ぶ、なじみ深い取り合わせの画題である。"}, {"t": "art", "f": "daikon_a3.jpg", "date": "1850年（江戸）", "place": "日本", "title": "應舉画譜より 大根（Radish from Ōkyo Picture Book）", "artist": "円山応挙（原画）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1985.376.x", "note": "応挙の画風を伝える木版の絵手本の見開き。墨の濃淡だけで、ちぢれる葉と根の白さを描き分けている。応挙の没後半世紀あまりのちの版行で、写生を重んじたその眼が台所の野菜にも向いていたことを伝える。"}, {"t": "art", "f": "daikon_a4.jpg", "date": "1903年", "place": "アメリカ", "title": "大根と赤ちゃん（The Daikon and the Baby）", "artist": "ヘレン・ハイド", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/77591", "note": "アメリカ生まれのハイドは1899年から東京に住み、日本の彫師・摺師と組んで木版画をつくったとされる。着物の子どもが、胴まわりほどもある大根を抱えて運ぶ。葉が頭上で額縁のようにめぐり、野菜が子どもの相棒になっている。"}, {"t": "photo", "f": "daikon_p1.jpg", "date": "いま", "place": "北海道・稚内", "title": "大根（写真）", "author": "Rick McCharles", "lic": "CC BY 2.0", "url": "https://commons.wikimedia.org/wiki/File:Wakkanai,_Japan_2011_Daikon_(6291773703).jpg", "note": "秋の終わりの稚内で、葉ごと竿に掛けられて干される大根の列。縦に割られたものも混じる。干して水分を抜くひと手間が、漬物や煮物の味の底をつくってきた。"}], "no": "第一景"}, {"id": "nasu", "kind": "yasai", "name": "茄子", "yomi": "なす", "en": "Eggplant", "rep": "nasu_a2.jpg", "lead": "インドに生まれ、奈良の都に届き、初夢の三番目に座った紫。花も実も、夏の畑でいちばん深い色をしている。", "layers": [["紫の正体", "ナス科ナス属の野菜で、トマトやジャガイモと同じ科に属する。食べているのは花のあとにふくらむ果実で、皮の紫はナスニンと呼ばれるアントシアニン系の色素とされる。うつむいて咲く薄紫の花は、実とよく似た色をしている。"], ["来歴", "原産はインド東北部のあたりとされ、日本へは中国を経て奈良時代までに伝わった。天平勝宝2年（750）の正倉院文書に「茄子進上」とあるのが古い記録のひとつとされる。賀茂なす・水なす・長なすなど、土地ごとに形のちがう品種が各地に育ってきた。"], ["文化", "初夢の「一富士二鷹三茄子」に選ばれ、お盆にはナスで牛をつくって先祖の帰りの乗り物にする地方がある。「秋茄子は嫁に食わすな」のことわざは、意地悪とも思いやりとも読まれ、解釈に諸説あるとされる。"]], "invite": "ナスを切ったら、切り口が空気にふれて色を変えていくのを一分だけ眺めてみる。変わる前の、種のほとんど見えない乳白色もおぼえておく。", "works": [{"t": "art", "f": "nasu_a1.jpg", "date": "1500年代（室町）", "place": "日本", "title": "胡瓜茄子図（Cucumber and Eggplants）", "artist": "山田道安", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1982.11", "note": "キュウリ一本とナス二つを、墨の濃淡だけで描いた室町の掛軸。東アジアで野菜の静物はめずらしい画題だが、簡素な題材ほど筆の力があらわれるとして、禅の周辺では好まれたとされる。へたのとげまで濃い墨のひと刺しで立っている。"}, {"t": "bun", "date": "1689年（元禄2）", "place": "日本", "title": "おくのほそ道", "author": "松尾芭蕉", "quote": "秋涼し手毎にむけや瓜茄子", "src": "『おくのほそ道』（元禄2年・1689）。金沢の段。本文は「芭蕉俳句全集」（Wikisource）等で照合", "note": "『おくのほそ道』の旅の途中、金沢の草庵に招かれた席での挨拶の句とされる。もてなしの瓜と茄子を、めいめいの手でむいて秋の涼しさを分け合う。"}, {"t": "bun", "date": "江戸時代", "place": "日本", "title": "初夢の俚諺", "author": "作者不詳（俚諺）", "quote": "一富士二鷹三茄子", "src": "江戸時代の俚諺。江戸の国語辞書『俚言集覧』に駿河の名物として「一富士二鷹三茄子」が見えるとされる", "note": "初夢に見ると縁起がよいとされるものの並び。駿河の名物を順に挙げた説、徳川家康の好みに結びつける説など、由来には諸説あるとされる。「四扇五煙草六座頭」と続ける言い方もある。"}, {"t": "art", "f": "nasu_a2.jpg", "date": "1829年（江戸）", "place": "日本", "title": "茄子に花と蝶（Eggplant with fruit and flowers）", "artist": "大西椿年", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/103309", "note": "花と若い実と熟れた実がひと枝にそろい、蝶が一匹近づいてくる木版。ナスの花は咲けばほとんど実を結ぶとされ、「親の意見となすびの花は千に一つも無駄はない」ということわざも、この性質から来ているとされる。"}, {"t": "art", "f": "nasu_a3.jpg", "date": "1924年ごろ", "place": "アメリカ", "title": "静物（Still Life）", "artist": "プレストン・ディキンソン", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1926.1664", "note": "白い鉢の真ん中に、深い紫のナスがひとつ。レモンの黄や瓶の茶にかこまれて、いちばん暗い色が画面をどっしり支えている。1920年代のアメリカの画家の台所にも、インド生まれの野菜が並んでいた。"}, {"t": "photo", "f": "nasu_p1.jpg", "date": "いま", "place": "セネガル", "title": "茄子（写真）", "author": "Bluebirdie9717", "lic": "CC BY 4.0", "url": "https://commons.wikimedia.org/wiki/File:Eggplant_Harvest.jpg", "note": "西アフリカ・セネガルの農村、家庭菜園での収穫の山。インドで生まれたナスは、いまは世界中の畑で育つ。柵の網と点滴灌水のチューブに、日々の手入れの跡が写っている。"}], "no": "第二景"}, {"id": "kabocha", "kind": "yasai", "name": "南瓜", "yomi": "かぼちゃ", "en": "Pumpkin / Squash", "rep": "kabocha_a3.jpg", "lead": "十六世紀、船に乗って日本へ来た大きな実。畑のすみで太りながら、寓話になり、灯りになり、冬至の膳にのぼってきた。", "layers": [["ウリ科の大きな果実", "かぼちゃはウリ科カボチャ属。日本で食べられるのは、ねっとりした日本カボチャ、ほくほくした西洋カボチャ、ズッキーニなどペポカボチャの、おもに三種の総称とされる。食べている丸いところは果実そのもので、雄花と雌花が別々に咲く。"], ["名前はカンボジア", "原産は中南米とされ、十六世紀、カンボジアに寄港したポルトガル船が九州へ伝えたと言われる。寄港地の名がそのまま「カボチャ」になったとされ、唐茄子・なんきん・ぼうぶらといった別名にも、海を渡ってきた記憶が残っている。"], ["灯りになった野菜", "ハロウィンのジャック・オー・ランタンは、アイルランドなどの伝承では元はカブに彫られていたとされ、移民先のアメリカで、大きくて彫りやすい南瓜に置き換わったと言われる。かぶの景とこの景は、一つの灯りでつながっている。"]], "invite": "かぼちゃを切る前に、縦の筋を指で一周たどってみる。何本あったか、一行だけ書きとめる。", "works": [{"t": "art", "f": "kabocha_a1.jpg", "date": "1769年ごろ", "place": "イタリア", "title": "南瓜の釣り舟（A Pumpkin Used as a Fishing Boat）", "artist": "フィリッポ・モルゲン", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2023.19.7", "note": "月世界を旅した司教が見てきたもの、という趣向の空想版画連作の一枚。くり抜いた大南瓜が帆を張り、煙を上げて漁に出る。十八世紀のヨーロッパで、南瓜はすでに「乗り物になるほど大きい実」の代名詞だった。"}, {"t": "bun", "date": "文政期（1819〜21年ごろ）", "place": "日本", "title": "八番日記", "author": "小林一茶", "quote": "鶺鴒がたたいて見たる南瓜かな", "src": "『八番日記』（きごさい歳時記「南瓜」の項に所載）", "note": "セキレイは尾で地面をたたくように動く鳥。その仕草を、畑の南瓜の熟れ具合をたしかめる指先に見立てた。伝本により「たゝいて見たる南瓜哉」とも表記される。"}, {"t": "art", "f": "kabocha_a2.jpg", "date": "1878年", "place": "アメリカ", "title": "とうもろこし畑の南瓜（Pumpkins Among the Corn）", "artist": "ウィンズロー・ホーマー", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1942.1431", "note": "刈り入れどきのとうもろこし畑で、両手に一つずつ南瓜を提げて立つ人の木口木版。北米には先住民の時代から、とうもろこし・豆・南瓜を同じ畑で育てる作法が知られ、この取り合わせはその名残でもあるとされる。"}, {"t": "art", "f": "kabocha_a3.jpg", "date": "1881年", "place": "フランス", "title": "どんぐりと南瓜（The Acorn and the Pumpkin）", "artist": "ジュール・バスティアン＝ルパージュ", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/49071", "note": "題はラ・フォンテーヌの寓話（1679）と同じ。大きな南瓜は細い蔓に、小さなどんぐりは大樹に実る——その配分を訝った男の鼻先に、どんぐりが一粒落ちてくる話。手押し車の南瓜を前に、うつむいて考えこむ男の水彩。"}, {"t": "art", "f": "kabocha_a4.jpg", "date": "19世紀後半（明治期）", "place": "日本", "title": "南瓜を切る人の根付", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/59096", "note": "高さ3.4cmの木彫。帯から物を提げる留め具の根付に、大南瓜へ両手で刃を入れる人が彫られている。切り分けるのに力がいる野菜だからこそ、その一瞬が手のひらの意匠になった。"}, {"t": "bun", "date": "1902年（明治35）", "place": "日本", "title": "明治三十五年の句", "author": "正岡子規", "quote": "南瓜より茄子むつかしき写生哉", "src": "松山市立子規記念博物館「子規の俳句検索」", "note": "亡くなる年の句。絵でも句でも「写生」を説いた子規にとって、大きくおおらかな南瓜は描きやすく、艶をまとう茄子は難物だった。野菜を画題として見た、実作者の実感。"}, {"t": "photo", "f": "kabocha_p1.jpg", "date": "いま", "place": "アメリカ・マサチューセッツ州", "title": "南瓜（写真）", "author": "Bonnie Kittle", "lic": "CC0", "url": "https://commons.wikimedia.org/wiki/File:Pumpkin_Picking_(Unsplash).jpg", "note": "とうもろこし畑のへりに並んだ、収穫されたばかりの南瓜。ホーマーが1878年に彫った光景とほとんど同じ取り合わせが、いまも秋の農場に続いている。"}], "no": "第三景"}, {"id": "kabu", "kind": "yasai", "name": "かぶ", "yomi": "かぶ", "en": "Turnip", "rep": "kabu_a1.jpg", "lead": "春の七草の「すずな」。七世紀の詔に載り、藍色の器に描かれ、俳人の名の一字にもなった——日本の暮らしにいちばん長くいる丸のひとつ。", "layers": [["丸いのは根ではない", "かぶはアブラナ科アブラナ属。食べている丸い部分は、根そのものではなく、おもに胚軸（茎と根のあいだ）がふくらんだものとされる。白菜や小松菜、野沢菜と同じ種（Brassica rapa）の仲間で、葉もかぶ菜として食べられてきた。"], ["七世紀からの記録", "『日本書紀』には、持統天皇の詔（693年）で桑や栗とともに蕪菁（かぶ）の栽培を勧めたと記される。春の七草では「すずな」の名で数えられ、聖護院かぶ・天王寺蕪・温海かぶなど、土地の名を負った在来品種が各地に残る。"], ["灯りと物語", "ハロウィンのジャック・オー・ランタンは、アイルランドなどでは元はカブに彫られていたとされる。ロシア民話『おおきなかぶ』では、抜けないほど育った一株が人と動物を一列につなぐ。大きさも丸さも、物語の道具になってきた。"]], "invite": "かぶを手にしたら、丸い部分の下の細い根と、ひげ根の跡を探してみる。どこまでが「根」なのか、一行だけ。", "works": [{"t": "bun", "date": "中世（南北朝〜室町ごろ）", "place": "日本", "title": "春の七草の歌", "author": "詠み人知らず", "quote": "せり なずな ごぎょう はこべら ほとけのざ すずな すずしろ これぞ七草", "src": "七草の選は南北朝期の『源氏物語』注釈書『河海抄』に見えるとされる。末尾を「春の七草」とする伝本もある", "note": "「すずな」がかぶ、「すずしろ」が大根。正月七日の粥に若菜を入れる行事とともに伝わった数え歌で、かぶはこの一列に定位置を持ちつづけている。"}, {"t": "art", "f": "kabu_a1.jpg", "date": "17世紀なかば（江戸前期）", "place": "日本", "title": "蕪文の皿（Dish with Turnip）", "artist": "作者不詳（肥前・有田）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/50327", "note": "染付の藍一色で、葉を翻す蕪が一株。ごちそうではなく野菜そのものを、直径19cmの皿の真ん中に据えている。食べものをのせる器に、食べものの絵を描く——その素直さごと残った一枚。"}, {"t": "art", "f": "kabu_a2.jpg", "date": "1742年", "place": "フランス", "title": "かぶをむく女（La Ratisseuse）", "artist": "フランソワ・ベルナール・レピシエ（シャルダン原画）", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/202417", "note": "台所の腰掛けで、膝の上のかぶに小刀を当てる女性。シャルダンの油彩を版画にした一枚で、足元には皮をむかれる前のかぶが葉ごと転がる。余白の詩句は、素朴な野菜が食卓を毒から遠ざけていた昔を讃えている。"}, {"t": "art", "f": "kabu_a3.jpg", "date": "1814年ごろ", "place": "日本", "title": "蜂と蕪の茎（『北斎写真画譜』より）", "artist": "葛飾北斎", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/33404", "note": "画帖の見開きに、葉を大きくうねらせた蕪が一株と、離れたところに蜂が一匹。地味な冬菜を、これだけ動きのある画面にしてしまう線の力。緑のにじみが、葉のやわらかさまで運んでいる。"}, {"t": "art", "f": "kabu_a4.jpg", "date": "1815年ごろ", "place": "日本", "title": "膳の上のサヨリと蕪（摺物）", "artist": "柳々居辰斎", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/54962", "note": "狂歌を添えて仲間内に配られた正月の摺物。漆の盆にサヨリが一尾、かたわらに葉つきの白い小蕪。新年のごちそうの脇で、蕪がいちばん身近な白として画面を締めている。"}, {"t": "bun", "date": "1898年（明治31）", "place": "日本", "title": "明治三十一年の句", "author": "正岡子規", "quote": "蕪肥えたり蕪村生れし村の土", "src": "松山市立子規記念博物館「子規の俳句検索」", "note": "蕪の字を名に持つ蕪村へ、肥えた蕪でオマージュを送った句。ただし蕪村の「蕪」は野菜ではなく「荒れる」の意で、陶淵明「帰去来辞」に由来するとされる。蕪村を敬慕した子規は、蕪村忌の句も数多く残した。"}, {"t": "photo", "f": "kabu_p1.jpg", "date": "いま", "place": "日本・大阪", "title": "かぶ（写真）", "author": "Kingfisher", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Tennoji_Turnip.JPG", "note": "大阪の小学校で育てられた、なにわの伝統野菜・天王寺蕪。子規が「此頃は蕪引くらん天王寺」と詠んだ蕪は、いまは教室のそばの畑で受け継がれている。"}], "no": "第四景"}, {"id": "uri", "kind": "yasai", "name": "瓜", "yomi": "うり", "en": "Melon / gourd", "rep": "uri_a3.jpg", "lead": "古く「うり」といえば、この黄色い真桑瓜のことだったとされる。巻きひげでつかまりながら地を這い、夏の日ざしの下で水を抱えこんで太る、いちばん涼しい実。", "layers": [["つるの先で実る", "ウリ科は、巻きひげで支えをつかみながら地を這い、棚を登るつる性の草。多くはひとつの株に雄花と雌花が別々に咲き（雌雄異花・同株）、花粉は蜂などの虫が運ぶとされる。ただし現在よく育てられるキュウリには、受粉しなくても実が太る「単為結果性」の強い品種が多いとされ、同じ科のなかでも実り方はひと通りではない。"], ["ほとんどが水", "食べているのは、花のあとにふくらむ果実そのもの。その大半は水である。日本食品標準成分表（八訂・増補2023年）では、きゅうり（果実・生）の可食部100 gのうち水分が95.4 g、エネルギーは13 kcal。夏の畑が根から汲み上げた水を、かたちのあるまま手渡されているようなものといえる。"], ["真桑瓜の名は、村の名", "日本には古く中国を経て伝わったとされ、各地の遺跡から瓜の種子が出土している。マクワ（真桑）の名は、良品の産地とされた美濃国真桑村（現在の岐阜県本巣市）の地名に由来するとされ、名前そのものが土地の名前でできている。甘いメロンが広まる昭和なかばまで、日本の夏の瓜といえばこの黄色い実だった。"]], "invite": "きゅうりでも真桑瓜でもいい。切る前に手のひらにのせて重さを覚え、その重さのほとんどが水だと思ってから、もう一度持ってみる。", "works": [{"t": "bun", "date": "8世紀（奈良時代）", "place": "日本", "title": "万葉集 巻五・八〇二", "author": "山上憶良", "quote": "瓜食めば子ども思ほゆ栗食めばまして偲はゆ", "src": "『万葉集』巻五・802（題詞「子等を思ふ歌一首[并せて序]」）。本文は「たのしい万葉集」（art-tags.net）で照合", "note": "引いたのは長歌の冒頭四句で、歌はこのあと「いづくより来りしものぞ眼交にもとなかかりて安寐し寝さぬ」と続く長歌である。よく知られる反歌「銀も金も玉も何せむに…」は次の803番。瓜も栗も、当時は子どもにとってのごちそうだったとされる。"}, {"t": "art", "f": "uri_a1.jpg", "date": "1200年代（高麗）", "place": "朝鮮半島", "title": "瓜形の青磁水注（Melon-shaped Ewer with Incised Peony Design）", "artist": "作者不詳（高麗）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1921.618", "note": "高さ18cmほど。縦の稜を立てた胴はそのまま一個の瓜で、蓋のつまみと把手が蔓のように反り返る。胴には小花と蔓の文様が淡くめぐる。美術館の韓国語表記は「참외모양（まくわ瓜のかたち）」——器のかたちの手本として、東アジアでは瓜が選ばれてきた。"}, {"t": "bun", "date": "1689年（元禄2）", "place": "日本・出羽（酒田）", "title": "元禄二年の句（真蹟懐紙）", "author": "松尾芭蕉", "quote": "初真桑四つにや断たん輪に切らん", "src": "出典は真蹟懐紙。本文は「芭蕉俳句全集」（山梨県立大学）・きごさいBASE「季語別 芭蕉全句集」で照合", "note": "『おくのほそ道』の旅の途中、象潟から酒田へ戻り、富商の家の納涼の席で詠まれた句とされる。「句のない者は食べさせない」と戯れに言われて出た挨拶で、この夏はじめての真桑瓜を、四つに割ろうか輪切りにしようかと迷ってみせている。きごさいBASE では「初真桑四にやわらン輪に切らン」の表記。"}, {"t": "art", "f": "uri_a2.jpg", "date": "1700〜1750年ごろ（清）", "place": "中国・蘇州", "title": "西瓜と葡萄（Watermelon and Grapes）", "artist": "作者不詳（蘇州）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2025.115", "note": "黒漆の台にのせた大皿へ、切り分けた西瓜と葡萄を高く盛った多色摺の版画。赤い果肉と黒い種、白い皮ぎわまで版を分けて刷ってある。十七世紀以降、蘇州など江南の町では色刷りの一枚絵が壁を飾る品として売られたとされる。西瓜の名は、西から伝わった瓜の意とされる。"}, {"t": "art", "f": "uri_a3.jpg", "date": "1812年", "place": "イギリス", "title": "『ポモナ・ブリタニカ』第72図 アミキュア（メロン）", "artist": "ジョージ・ブルックショー", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2020.167", "note": "暗い背景に、丸ごとの一果と切り分けた一片、そして黄色い花と巻きひげのついた蔓を一枚に収めている。果実をしばしば実物大で、花と葉まで添えて描いたのがこの図譜の作法で、多くはハンプトン・コート宮などの庭で育てられた果実を写したものとされる。瓜が「実」だけでなく「つる草」であることが、この一枚で見てとれる。"}, {"t": "art", "f": "uri_a4.jpg", "date": "19世紀（江戸〜明治）", "place": "日本", "title": "胡瓜を持つ河童の根付（Kappa with a cucumber）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/59126", "note": "高さ3.8cmの木彫。あぐらをかいた河童が、いぼの立った緑の胡瓜を膝に抱えている。頭の皿、くちばし、浮き出たあばらまで彫り分けられている。水難を避けるために川へ胡瓜を供えた風習が、やがて「河童の好物」の話になったとされ、「かっぱ巻き」の名もそこから来ると言われる。"}, {"t": "photo", "f": "uri_p1.jpg", "date": "いま", "place": "日本", "title": "黄金まくわ（写真）", "author": "Uo3rt", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Sold_ougon-makuwa.JPG", "note": "緑の籠に山盛りの黄色い瓜と、ボール紙に「地黄まつか」と手書きされた値札。撮影は6月末。ウィキメディア・コモンズでは大和伝統野菜「黄金まくわ」として分類されている。芭蕉が四つに割ろうか輪切りにしようか迷った初真桑も、店先ではおよそこんな色をしていたはずである。"}], "no": "第五景"}, {"id": "imo", "kind": "yasai", "name": "芋", "yomi": "いも", "en": "Taro / yam", "rep": "imo_a1.jpg", "lead": "山でとれる芋に対して、里でつくる芋。旧暦八月十五日の月は芋名月とも呼ばれ、掘りたての里芋を供えてきた——秋のまんなかで、いちばん月に近い野菜。", "layers": [["食べているのは、根ではなく茎", "サトイモはサトイモ科サトイモ属。食べている「芋」は根ではなく、地下の茎が肥大したもので、塊茎（かいけい）あるいは球茎（きゅうけい）と呼ばれるとされる（両者は厳密には区別しにくいとされる）。中心の親芋のまわりに子芋がつき、その先に孫芋がつく——ひと株が家族のように増える。葉柄は干して「ずいき」として食べられてきた。"], ["水をはじく葉", "サトイモの葉に落ちた雨は、広がらずに玉になって転がる。葉の表面が細かい突起におおわれ、さらにろう（ワックス）の層があるため、水とふれる面積が小さくなるからだとされる。ハスの葉と同じしくみで、ロータス効果と呼ばれる。葉柄はふちではなく葉の裏の中ほどにつく、盾のような形の葉。"], ["芋名月", "旧暦八月十五日の月は中秋の名月と呼ばれ、あわせて芋名月とも呼ばれる。掘りたての里芋を供える風習によるとされる。翌月、旧暦九月十三日の十三夜は豆名月・栗名月。稲より前からの作物だから供えるのだ、という説も語られるが、由来には諸説あり、はっきりしていない。"]], "invite": "土のついた里芋を洗ったら、表面を横にめぐる輪を探してみる。茎が肥大したものなので、そこには葉のついていた跡が残っているとされる。", "works": [{"t": "bun", "date": "1687年（貞享4）", "place": "日本", "title": "鹿島詣（鹿島紀行）", "author": "松尾芭蕉", "quote": "芋の葉や月待つ里の焼畑", "src": "『鹿島詣』（貞享4年8月・1687）。原文の表記は「いもの葉や月待里の焼ばたけ」。芭蕉DB「芭蕉俳句全集」ときごさい歳時記「芋」の項で照合", "note": "鹿島へ月を見に出かけた旅の途中の句。焼いた畑に里芋の葉が茂り、村じゅうが月の出を待っている。芋と月が、一句のなかに並んで置かれている。"}, {"t": "bun", "date": "18世紀（江戸中期）", "place": "日本", "title": "太祇句集 後篇", "author": "炭太祇", "quote": "芋の露野守の鏡何ならむ", "src": "きごさい歳時記「芋」の項（出典『太祇句集後篇』）。「何ならん」の表記でも伝わる", "note": "野守の鏡は、和歌に詠まれた伝説の鏡で、野に溜まった水を指すともいわれる。芋の葉にのった露の玉を覗きこんで、あの鏡もこれくらいのものだったのでは、と言っている。太祇は蕪村と親交のあった江戸中期の俳人（1709〜1771）。"}, {"t": "art", "f": "imo_a1.jpg", "date": "1801年（享和元）", "place": "日本", "title": "月見の宴（『絵本四季花』巻二より）", "artist": "喜多川歌麿", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/34789", "note": "絵本の見開き。左上にまるい月、縁側へ出た女がそれを仰ぎ、障子のうちにも三人。縁の奥には白木の台があり、青竹の花入と秋草がのっている——側面に丸い刳り抜きのあるこの台は、供物をのせる三方とみられる。旧暦八月十五日の月は芋名月とも呼ばれ、里芋を供えたとされる。手前は町屋の屋根と、若い松。"}, {"t": "art", "f": "imo_a2.jpg", "date": "1880年ごろ", "place": "オランダ", "title": "芋の皮をむく（Peeling Potatoes）", "artist": "ヨゼフ・イスラエルス", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1921.1000", "note": "石畳の台所。藁座の椅子に腰かけた人が小刀で芋の皮をむき、隣の子どもが膝に鉢を抱えて、むいた芋を受けている。床には籠と脱いだ履物。イスラエルスはオランダの漁村や農家の日々を、こうした腐食銅版（エッチング）で繰り返し描いた。じゃがいもは南米原産のナス科で里芋とは別の植物だが、日本語ではどちらも「芋」と呼ぶ。"}, {"t": "art", "f": "imo_a3.jpg", "date": "1883年", "place": "フランス", "title": "市庁舎に届く芋（Potatoes Arriving at the Hôtel de Ville）", "artist": "オーギュスト・ルペール", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2007.271", "note": "パリの河岸に平たい舟がびっしりと着き、甲板には芋を盛った籠が並ぶ。人が籠を担いで斜路を上がり、岸には荷馬車の列。奥には煙を上げる船と、川向こうの街。ひとつの都市を食べさせるために、これだけの量が毎日運ばれてきた。木口木版の細い線が、その数を刻むように積み上げている（彫版はアンリ・ピエール・パイヤール）。"}, {"t": "art", "f": "imo_a4.jpg", "date": "20世紀", "place": "パプアニューギニア", "title": "芋の仮面（Yam Mask）", "artist": "作者不詳（アベラムの人びと）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1998.84", "note": "植物の繊維を編み、赤・黄・黒の顔料で彩った、高さ47cmほどの仮面。細長い顔のうしろに、扇のような弧が三重にひらく。美術館の解説によれば、アベラムの男たちは一メートルを超えるほど大きなヤム芋を育てて競い、収穫した芋をこうした編みの仮面で飾って披露するとされる。ヤム芋（ヤマノイモの仲間）はサトイモとは別の科の植物だが、芋に顔を与えるという発想は、供える芋の遠い親戚に見える。"}, {"t": "photo", "f": "imo_p1.jpg", "date": "いま（2014年）", "place": "インド・西ベンガル州", "title": "サトイモの葉と水玉（写真）", "author": "Arupparia", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Water_Drops_on_Taro_Leaf.jpg", "note": "雨季の芋畑。葉のふちに沿って、水が玉のまま並んでいる。葉の表面の細かい突起と、その上のろうの層が、水とふれる面積を小さくしているとされる。太祇が覗きこんだ「芋の露」も、この玉のことだった。"}], "no": "第六景"}, {"id": "mame", "kind": "yasai", "name": "豆", "yomi": "まめ", "en": "Beans / pulses", "rep": "mame_a4.jpg", "lead": "莢のふくらみを外から数えられる、めずらしく正直な実。根には土の細菌を住まわせて空気から窒素を取りこみ、育った土に肥やしを残していく——食べものであると同時に、土をつくる作物でもある。", "layers": [["根の粒が、空気から窒素をとる", "豆はマメ科の植物の種子。マメ科の多くは、根に根粒（こんりゅう）という小さなこぶをつくり、そこへ根粒菌という細菌を住まわせる。根粒菌はニトロゲナーゼという酵素で空気中の窒素をアンモニアに変えて植物に渡し、植物は光合成でつくった糖を菌に渡すとされる（窒素固定）。窒素肥料に頼りきらずに育ちうるのはこのためで、豆を輪作に組みこんで土を肥やしてきたのは、この見えない同居人のはたらきによるとされる。"], ["姿を変えて台所にいる大豆", "大豆は粒のまま食べるだけでなく、加工されて姿を変えてきた。国立国会図書館の解説によれば、味噌と醤油はどちらも中国から伝わった醤（ひしお）に由来し、大宝律令（701年）にその名が記録されるという。豆腐は奈良時代に伝わり、鎌倉時代に精進料理として武家・公家へ広まって、江戸時代には庶民の食べものになった。天明2年（1782）には豆腐料理だけを集めた『豆腐百珍』が出ている。糸を引く納豆は日本独特のものとされるが、由来ははっきりせず、諸説あるとされる。"], ["撒く豆、食べる豆", "節分はもともと季節の変わり目を指す言葉で、いまは立春の前日をいう。中国から伝わった追儺（ついな）の行事は日本では8世紀初め、706年に初めて行われたとされ、のちに寺社の「豆打ち」と結びついて、いまの豆まきの形になったといわれる。撒くのは炒った大豆で、「福は内、鬼は外」と囃し、年の数だけ食べる。なぜ豆なのかは、大豆が鬼毒を消すと中国の本草書にあるから、「魔滅（まめ）」に通じるから、など諸説あるとされ、はっきりしていない。"]], "invite": "枝豆の莢を明るいほうへかざしてふくらみを数え、株ごと手に入ったなら根も洗って、小さな粒がついていないか探してみる。", "works": [{"t": "bun", "date": "8世紀（奈良時代）", "place": "日本", "title": "万葉集 巻二十・四三五二", "author": "丈部鳥（はせつかべのとり）", "quote": "道の辺の茨のうれに延ほ豆のからまる君をはかれか行かむ", "src": "『万葉集』巻二十・4352（防人歌）。原文は「美知乃倍乃 宇万良能宇礼尓 波保麻米乃 可良麻流伎美乎 波可礼加由加牟」。本文は Wikisource「万葉集/第二十巻」と「たのしい万葉集」（art-tags.net）で照合", "note": "天平勝宝7年（755）に集められた防人歌の一首とされる。道ばたの茨のさきに這いのぼる豆のつるが枝にからむように、すがりつく人を置いて行かねばならない、と詠む。豆をまず「巻きつくもの」として見た目が、千二百年以上前の一首に残っている。"}, {"t": "art", "f": "mame_a1.jpg", "date": "1533年", "place": "ドイツ", "title": "豆の莢（The Pea Pod）", "artist": "マイスター H. L.", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1925.45", "note": "ふくらんだ莢をつないで楕円の輪をつくり、四方を紐で結んだ銅版画。莢ごしに、中の豆が一列に並んでいるのが透けて見える。輪のなかでは翼のある童子がふたり、身の丈ほどもある莢を抱えこみ、ひとりが取り出した粒を口へ運んでいる。足もとにはこぼれた豆と空の莢。左下に「1533」の年記。本名の伝わらない版画家で、作品に残る組み合わせ文字から「マイスター H. L.」と呼ばれている。"}, {"t": "art", "f": "mame_a2.jpg", "date": "1794〜95年（寛政6〜7）", "place": "日本", "title": "扇面お多福図（節分に黒豆を撒くお多福）", "artist": "東洲斎写楽", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/18739", "note": "扇のかたちに刷られた一枚。丸い頬のお多福が、豆をいっぱいに入れた四角い枡を胸もとに抱え、右手を大きくひらいて放ったところ。左上に五つ六つ、粒が宙に散っている。左中ほどに「寫樂画」の署名。美術館の題は「大晦日に鬼を追い払うために黒豆を撒くお多福」で、立春を年の始まりとみる考えから、節分は年の変わり目とされてきた。写楽の活動が確認できるのは寛政6年（1794）5月からのおよそ10か月で、残る作の多くは役者絵とされる。そのなかでは珍しい、台所に近い画題である。"}, {"t": "art", "f": "mame_a3.jpg", "date": "1798〜99年ごろ（寛政10〜11）", "place": "日本", "title": "祇園豆腐（「婦人手業拾二工」より）", "artist": "喜多川歌麿", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/23895", "note": "女たちの手仕事を十二の場面で見せた揃物の一枚。立った女が幅の広い包丁の柄を握り、低い台にのせた白い塊へ刃を当てている。塊はすでに薄く何枚にも切り分けられ、右手の籠には細い串の束。左上には「祇園」と染めた提灯。祇園豆腐は八坂神社の門前の茶屋で売られた田楽豆腐で、薄く切った豆腐に串を刺して焼き、味噌をのせた京の名物とされる。畑の大豆が、水と型と火を通ってここまで来ている。"}, {"t": "art", "f": "mame_a4.jpg", "date": "1810年代（文化〜文政）", "place": "日本", "title": "節分に撒く豆（「浅草側伊勢暦」より・『春雨集』巻二所収）", "artist": "窪俊満", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/54994", "note": "狂歌を添えて仲間内に配られた摺物。幾何文様の布の上に、紅白に彩られた脚つきの角い器が置かれ、炒った豆が山盛りになっている。手前にはこぼれた粒が転がり、豆の一つひとつに黒い臍（へそ）まで摺り分けてある。黒漆のかぶりもの、赤い実と黄の花の枝、そして棘のある葉の枝に添えられた魚の頭——節分に戸口へ挿す柊鰯（ひいらぎいわし）とみられる（美術館の解説はここに触れておらず、読みはこちら側にある）。署名は「尚左堂」。左手で描いたことに由来する俊満の号とされる。"}, {"t": "bun", "date": "文政期（1819〜21年ごろ）", "place": "日本", "title": "八番日記", "author": "小林一茶", "quote": "三ツ子さへかりりかりりや年の豆", "src": "きごさい歳時記「豆撒」の項（出典『八番日記』）", "note": "年の豆は、節分に撒き、年の数だけ食べる炒り大豆のこと。三つの子までが、かりりかりりと音を立てて噛んでいる。音だけで場面を立ててしまう一茶の句で、堅い豆に当たる小さな歯の力までが伝わってくる。"}, {"t": "photo", "f": "mame_p1.jpg", "date": "いま（2011年）", "place": "日本・兵庫県丹波篠山市", "title": "丹波黒の枝豆（写真）", "author": "松岡明芳", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File:Tamba-guro_%E4%B8%B9%E6%B3%A2%E9%BB%92_%E6%9E%9D%E8%B1%86_DSCF9751.jpg", "note": "十月はじめ、黒大豆「丹波黒」の畑。茎にびっしりと莢がつき、一つひとつが細かい毛におおわれている。ふくらみの数がそのまま中の豆の数で、若いうちに採れば枝豆、畑で完熟させて乾かせば黒豆になる。写楽の枡にも一茶の口にもあったのは、こうして実った豆である。"}], "no": "第七景"}, {"id": "hisago", "kind": "yasai", "name": "瓢", "yomi": "ひさご", "en": "Gourd / calabash", "rep": "hisago_a3.jpg", "lead": "乾かした実は、軽くて、水に浮いて、水を通さない。食べるためより先に、人はこの実を容れ物にした——人類がいちばん早くから育ててきた作物のひとつとされる、うつわになった野菜。", "layers": [["食べるより、容れ物として", "ヒョウタンはウリ科ユウガオ属のつる草で、瓢箪も夕顔も同じ種（Lagenaria siceraria）の仲間とされる。原産はアフリカとされ、人類が最初期から栽培した作物のひとつに数えられる。日本では福井県の鳥浜貝塚から縄文時代の種子が出土しており、稲より古い栽培植物とも言われる。実は熟すと外皮が硬くなり、中を抜いて乾かせば、軽く、水に浮き、水を漏らさない——食用よりも、水や酒を入れる器、あるいは楽器として世界へ広まったとされる。"], ["苦い実と、苦くない品種", "ウリ科の実にはククルビタシン類という苦味成分が含まれることがあり、瓢箪の実も強い苦味をもつものが多いとされる。食用にされるのは苦味の少ない品種で、干瓢はその果肉を細く剥いて干したもの。ただし食用品種でも、ごくまれに苦味の強い個体が出ることがあり、食べると唇のしびれ・吐き気・嘔吐・下痢などの食中毒を起こした例が報告されている。自治体は「調理前に実や茎を切って軽く味見をし、苦味がある場合は食べない」よう注意を呼びかけている（長野県「激しい苦みのあるウリ科植物にご注意ください」ほか）。"], ["瓢箪から駒", "思いもよらないことが起こるたとえ。由来は、中国の仙人・張果老が驢馬を瓢箪に収めて持ち歩いたという伝説と結びつけて語られるが、諸説あるとされる。日本の古い記録にも瓢は登場する。『日本書紀』仁徳天皇十一年の段では、川の神への人身御供に指名された茨田連衫子（まむたのむらじころものこ）が、瓢を二つ川へ投げ「本当に私が欲しいなら、これを沈めてみせよ」と言った。原文に「匏（ひさご）浪の上に転じて沈まず」とあり、沈まなかったので彼は助かる。浮くことそのものが、この実の力だった。"]], "invite": "瓢箪の形をした器を見かけたら、そのくびれに指を掛けてみる。実がもともと持っていたかたちが、そのまま手の掛かりになっている。", "works": [{"t": "art", "f": "hisago_a1.jpg", "date": "前180年〜500年ごろ（ナスカ）", "place": "ペルー南海岸", "title": "儀礼の装いの人物を刻んだ瓢（Gourd with Rattle Incised with Costumed Ritual Perfomer）", "artist": "作者不詳（ナスカの人びと）", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/91759", "note": "高さ13.2cm、卵形の実の表面に線を彫っている。上段は目と口だけの簡素な顔、下段は同心円の目に歯を並べた口、左右へ羽のような飾りが放射する顔。美術館の素材表記はそのまま「瓢（Gourd）」で、器そのものが実である。乾いた実は軽く、水を通さず、刃を当てれば線が彫れる。土を焼くよりも前から、人はこの実を器にしてきたとされる。"}, {"t": "bun", "date": "1330年ごろ（鎌倉末）", "place": "日本", "title": "徒然草 第十八段", "author": "兼好法師", "quote": "なりひさごといふ物を、人の得させたりければ、ある時木の枝にかけたりければ、風に吹かれて鳴りけるを、かしがましとて捨てつ", "src": "『徒然草』第十八段。本文はウィキソース『徒然草（校註日本文學大系）』18 の全文で照合", "note": "中国の隠者・許由の話。何も持たず、手ですくって水を飲んでいた許由に、人が瓢をひとつ与えた。木の枝に掛けておくと風に鳴ったので、やかましいと捨ててしまい、また手で水を飲んだ——という一段。持たないことを説く文章のなかで、いちばん少ない持ちものとして選ばれたのが、この実だった。"}, {"t": "art", "f": "hisago_a2.jpg", "date": "1500年代（明）", "place": "中国", "title": "仙人 李鉄拐（The Immortal Li Tieguai）", "artist": "蘇文南", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1973.158", "note": "高さ41.8cmの銅像。ぼろの衣を肩から落とし、あばらを浮かせ、裸足で口を開けて立つ。腰には葉を綴った帯、そしてその脇に、上下二段にくびれた小さな瓢箪がひとつ下がっている。両手は胸の前にそろえられ、右のこぶしには杖を通す孔が空いているが、いまその杖はない（美術館の解説は右手に鉄の杖、左手に丸薬とし、瓢から病人に薬を出すとされる、と記す）。背面には「蘇文南製」の四字が刻まれる。"}, {"t": "bun", "date": "1680年代（江戸前期）", "place": "日本", "title": "栞集", "author": "松尾芭蕉", "quote": "ものひとつ我が世はかろき瓢かな", "src": "きごさい歳時記「青瓢」の項（出典『栞集』）で照合。ウィキソース「芭蕉俳句全集」（無季の部）では「物ひとつ瓢はかろき我が世哉」の語順で載る", "note": "持ちものは瓢がひとつ、それだけの、軽い暮らし。芭蕉が米入れにしていた大きな瓢に、友人の山口素堂が「四山瓢」と銘をつけたという話とともに語られることが多い。語順の違う伝わり方をする句で、「ものひとつ瓢はかろき我世かな」の形でも知られる。"}, {"t": "art", "f": "hisago_a3.jpg", "date": "1700年代（江戸）", "place": "日本", "title": "菊文の瓢箪籠（Gourd Basket with Chrysanthemum Design）", "artist": "伝 尾形光琳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1963.101", "note": "幅30.2cmの籠。実を横に切り開いて器とし、切り残した細い帯を弓なりに立てて手にしている。胴には白い菊がいくつも盛り上がり、緑の葉がめぐる。美術館の解説によれば、菊は白い胡粉（ジェッソ）を盛って浮き彫りにしたもので、内側には金が張られ、底に尾形光琳の署名があるという（美術館の表記は「伝 尾形光琳」）。地の茶色は塗った色ではなく、実の皮そのものである。"}, {"t": "art", "f": "hisago_a4.jpg", "date": "1700年代〜1800年代なかば（江戸）", "place": "日本・備前", "title": "木の栓のついた瓢形壺（Double Gourd Jar with Wooden Stopple）", "artist": "作者不詳（備前焼）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1940.706", "note": "高さ約16cm（美術館の記載は栓ありで16.9cm、栓なしで15.6cm。写真では栓が外されている）。上下二つのふくらみが細いくびれでつながり、口は小さくすぼまって縁が丸く外へ返る。上半は飴色に澄み、下半には黄と黒と赤褐がまだらに流れる。備前焼は釉薬をかけず、窯の中の灰と炎だけで表面が決まるとされる。実を乾かした瓢が先に器だったことを思えば、これは器が実のかたちを写した一点ということになる（読みはこちら側にある）。"}, {"t": "photo", "f": "hisago_p1.jpg", "date": "いま（2010年）", "place": "日本（撮影地の記載なし）", "title": "棚から下がる瓢箪（写真）", "author": "Yoko Nekonomania", "lic": "CC BY 2.0", "url": "https://commons.wikimedia.org/wiki/File:Bottle_Gourd_-_Flickr_-_nekonomania.jpg", "note": "棚の下から見上げた一枚。手前の実は上下二段にくびれた瓢箪型で、皮はまだ青みを残した白。表面にうっすら縦の筋が走る。奥には丸いもの、細長いものがぼやけて下がっていて、ひとつの棚に形のまるでちがう実が並んでいるのがわかる。撮影は8月半ば。コモンズの説明は日本語で「でっかい瓢箪がぶら下がってた。」の一文だけである。"}], "no": "第八景"}, {"id": "morokoshi", "no": "第九景", "kind": "yasai", "name": "玉蜀黍", "yomi": "とうもろこし", "en": "Maize / corn", "rep": "morokoshi_a2.jpg", "lead": "アメリカ大陸で、人が何千年もかけてつくった草。野生の祖先テオシントは熟すと穂が節ごとに折れて種を散らすが、玉蜀黍の粒は芯から離れず、何枚もの皮に包まれたまま落ちない——人が皮をむいて播かなければ、次の年がない。日本語の名もヨーロッパの古い呼び名も「遠くから来たもの」と言っているが、どこから来たのかを言い当てているのは英語の maize だけである。", "layers": [["名前は、そろって来歴を取り違えている", "「とうもろこし」は、唐（とう）と唐土（もろこし）という、どちらも中国を指す語が重なった名だとされる。漢字の玉蜀黍も、蜀黍（もろこし＝ソルガムの類）に玉のような粒がついたもの、という見立て。ヨーロッパでも同じことが起きていて、ドイツ語では Türkischer Weizen（トルコの小麦）、イタリア語では granturco（トルコの穀）と呼ばれてきた。原産はそのどちらでもなく、メキシコを中心とする中央アメリカ。出どころを名に残しているのは英語の maize で、スペイン語 maíz を経て、カリブ海の島々のタイノ語 mahiz にさかのぼるとされる。この草を最初に呼んでいた人たちの言葉は、そこにだけ残っている。"], ["粒が、こぼれないように変えられた", "イネ科の一年草。ひと株に雄花と雌花が別々につき（雌雄異花・同株）、茎の先に立つ穂が雄花、葉のつけ根から出るのが雌花で、花粉は風が運ぶ。穂から垂れる「ひげ」は雌花の花柱で、一本が一粒につながっている。祖先はメキシコに自生するテオシントという草とされ、栽培化はおよそ九千年前にさかのぼると考えられている。テオシントの穂は熟すと軸が節ごとに折れて実を散らすが、玉蜀黍の芯は折れず、粒は何枚もの苞葉（ほうよう）に包まれたまま外へ出ない。自力で種を散らせない——人が皮をむいて播くことでしか次の世代が生まれない植物になっている。"], ["灰を入れてから、粉にする", "メソアメリカでは古くから、玉蜀黍を石灰や灰を溶かした湯で煮てから皮を外し、挽いてきた。ニシュタマル（nixtamal）と呼ばれる手順で、これを経ると生地がまとまり、粒に含まれるナイアシン（ビタミンB群のひとつ）が人に利用しやすい形になるとされる。十六世紀以降、この手順を伴わずに粒だけが海を渡った先では、玉蜀黍に偏った食事の地域でペラグラという欠乏症が広がった、と説明されることが多い。畑のほうにも組み合わせがあって、玉蜀黍・豆・カボチャを一緒に育てるミルパでは、玉蜀黍が豆の支柱になり、豆が窒素を供給し、カボチャが地面を覆って乾きと雑草を抑えるとされる。粒だけでなく、育て方と調理法をひと組にして手渡されてきた作物である。"]], "invite": "皮つきのとうもろこしを買ったら、むく前にひげを一本つまんで引いてみる。ひげは雌花の花柱で、もとは一本が一粒につながっている——束の数が、そのまま粒の数にあたる。", "works": [{"t": "art", "f": "morokoshi_a1.jpg", "date": "紀元前800〜前400年（オルメカ）", "place": "メキシコ・メキシコ盆地（トラパコヤか）", "title": "トウモロコシの神の横顔を刻んだ杯（Cup with Profile Head of the Maize God）", "artist": "作者不詳（オルメカ）", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/120476", "note": "高さ10センチほどの土器の杯。面いっぱいに、線刻で横顔がひとつ。大きな杏仁形の目、その下へ折れる帯、斜めにかかる網目——見えている面に、実の穂そのものは描かれていない。美術館がこれを〈トウモロコシの神〉と呼ぶのは、オルメカの図像を後世の研究が読み解いた呼び名であって、器にそう書いてあるわけではない。産地の記載も「トラパコヤか」と留保つき。二千数百年前のメキシコ盆地で、この顔が誰だったのかは、まだ確定していない。"}, {"t": "art", "f": "morokoshi_a2.jpg", "date": "50〜800年", "place": "ペルー", "title": "トウモロコシをかじる齧歯類（Rodent with Corn）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1951.180", "note": "高さ24センチほどの土器。座った齧歯類が、自分の胴ほどもある穂を両手で抱えて、上のほうをかじっている。粒はへこみを点々と打って表し、尾は穂の裏から回りこんで前へ出ている。頭のうしろから短い注ぎ口が立つ、液体を入れる壺。美術館の産地欄は「ペルー」だけで、モチェの作という説明は別の欄に置かれている——動物の肖像を得意とした人たちが、この草を、食べ手のほうから彫っている。"}, {"t": "art", "f": "morokoshi_a3.jpg", "date": "780〜810年（マヤ古典期後期）", "place": "グアテマラ・ペテン地方（ナランホ周辺）", "title": "トウモロコシの神として踊る（Vessel with Dancing Maize Gods）", "artist": "アフ・マシャム", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/65290", "note": "高さ24センチほどの円筒形の器。上端をマヤ文字の帯がめぐり、その下に、背中へ巨大な羽根の飾りを背負った人物が立つ。割れて継いだ跡が斜めに走っている。美術館の説明によれば、同じ姿が三面くり返され、これはトウモロコシの神の装いで踊る王で、器は葬りのためのもの——刈られて死に、また芽を出す穂に、人の生き死にを重ねている。館の解説は『ポポル・ヴフ』を引いてこれを読む。作者名の表記は解説文のなかで Aj Maxam と Ah Maxam に揺れている。"}, {"t": "art", "f": "morokoshi_a4.jpg", "date": "1400〜1500年（アステカ／メシカ）", "place": "メキシコ・テノチティトラン（現メキシコ市）", "title": "若いトウモロコシの女神シロネンの頭部（Head of Xilonen, the Goddess of Young Maize）", "artist": "作者不詳（アステカ／メシカ）", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/65328", "note": "玄武岩を彫った、高さ32センチほどの頭部。首から下は失われている。額の帯の上に、粒を並べたような丸い彫りが横へ連なり、その上から細い筋が扇のように立ち上がる——美術館はこれを、頭から生える二本のトウモロコシの穂と、背へ垂れるその毛（絹糸）と説明する。七月には、少女が女神に扮して踊る収穫はじめの祭が行われたという。シロネンの名は、ナワトル語で若い穂を指す語（xilotl）に由来するとされる。館の解説はこの名がのちのメキシコのスペイン語 elote（若い穂）になったと書くが、elote の語源は別のナワトル語 elotl に求めるのがふつうで、ここは説明が揺れている。"}, {"t": "bun", "date": "16世紀なかば（原本の成立）", "place": "グアテマラ（キチェ・マヤ）", "title": "『ポポル・ヴフ』第三部・第一章", "author": "キチェ・マヤの人びと（作者不詳）", "quote": "xa gana hal, zaki hal u tiohil", "src": "ブラッスール・ド・ブールブール編訳『Popol Vuh: Le livre sacré et les mythes de l'antiquité américaine』（パリ、1861年・著作権満了）第三部・第一章。キチェ語原文と対訳フランス語が見開きに組まれた196〜199ページを、インターネット・アーカイブ所蔵の同書の二本のスキャン全文（popolvuhlelivres01bras／popolvuhlelivres00bras_0）で照合。引用のローマ字表記はブラッスールの1861年の綴りによる", "note": "ブラッスールの対訳は « seulement du maïs jaune et du maïs blanc (entrèrent dans) leur chair »——「黄色い穂と白い穂だけが、彼らの肉になった」。最初の四人の人間が造られる場面で、泥でつくって崩れ、木でつくって心を持たなかった神々が、最後に挽いた玉蜀黍で人をこしらえる。トウモロコシが人を養う、ではなく、人がトウモロコシでできている、という順序で書かれている。いま伝わる本文は、十六世紀なかばにキチェ語をローマ字で書き留めたものを、十八世紀はじめにヒメネス神父が写した写本を通して残ったものとされる。"}, {"t": "art", "f": "morokoshi_a5.jpg", "date": "17世紀なかば（江戸前期）", "place": "日本", "title": "玉蜀黍と鶏頭（Maize and Cockscombs）", "artist": "作者不詳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/11272", "note": "金地の六曲屏風。左の三扇に鶏頭の赤、右の三扇に玉蜀黍の緑を置く。茎の先に白く広がるのが雄花、葉のつけ根から垂れる赤茶けた房が雌花のひげで、両方が描き分けられている。もとは一双で、残るのはその片方とされる。美術館は「植物図のような正確さ」と評し、日本にない穀物を画題に取りこんだことに、この時代の博物趣味を見ている。ポルトガル船が伝えたとされる十六世紀後半から数えて、百年ほどで、この草は金屏風の主役になっている。"}, {"t": "art", "f": "morokoshi_a6.jpg", "date": "1915年以前", "place": "コンゴ民主共和国またはアンゴラ", "title": "ふるい籠（Sifting Basket）", "artist": "作者不詳（チョクウェの作り手か）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1915.464", "note": "高さ39センチほど。下は縦に並べた芯を細い輪で幾重にも締め、上は口がラッパのように開き、そこだけ染めた繊維で斜めの綾が組んである。美術館の説明によれば、チョクウェの人びとは玉蜀黍を搗いて粉にし、この籠でふるって細かい粉を分けたという。玉蜀黍の姿は、どこにも描かれていない——アメリカ大陸を出た先に残るのは、絵ではなく、食べるための道具のほうだった。館の産地表記も「コンゴ民主共和国またはアンゴラ」「チョクウェの作り手か」と留保つきである。"}, {"t": "photo", "f": "morokoshi_p1.jpg", "date": "いま", "place": "（標本の写真・撮影地の記載なし）", "title": "テオシントの穂と、玉蜀黍の穂（写真）", "author": "John Doebley", "lic": "CC BY 3.0", "url": "https://commons.wikimedia.org/wiki/File:Maize-teosinte.jpg", "note": "上が野生のテオシントの穂、下が玉蜀黍の穂、あいだにあるのは両者の雑種。テオシントの穂は指ほどの長さで、硬い殻に包まれた実が十個ほど一列に並ぶだけ。熟すと軸が節ごとに折れ、実は殻ごと地面に散る。下の穂では、粒が芯にびっしり並び、軸は折れない。二つは同じ種の別の亜種とされ、交配すると実がなる——中央の穂が、その証拠になっている。この一枚のあいだにあるのが、九千年ほどの人の手である。"}]}, {"id": "tougarashi", "no": "第十景", "kind": "yasai", "name": "唐辛子", "yomi": "とうがらし", "en": "Chili pepper", "rep": "tougarashi_a4.jpg", "lead": "辛いは、味ではない。カプサイシンが、熱と痛みを受け取る神経のスイッチ（TRPV1）を押すので、焼かれてもいない舌が焼かれたと感じている。アメリカ大陸にしかなかったこの実が海を渡って、まだ五百年ほど——韓国も四川もハンガリーもタイも、その辛さは、その土地でいちばん古い味ではない。", "layers": [["名前が、そろって出どころを指しそこねている", "メキシコのナワトル語では chīlli（チリ）、カリブ海の島々のタイノ語では axí（アヒ）。ヨーロッパへ最初に持ち帰ったコロンブスは胡椒を探していたので、これを pimienta（胡椒）と呼んだ——英語の pepper はそこから来ている。黒胡椒はコショウ科、唐辛子はナス科で、縁もゆかりもない。日本では南蛮胡椒、蕃椒（ばんしょう）、そして唐辛子。唐は中国を指すが、中国から来たわけではない。九州には、いまも唐辛子を「胡椒」と呼ぶ言い方が残る（柚子胡椒の胡椒がこれ）。朝鮮半島では고추（コチュ）で、十七世紀初めの記録には南蛮椒、倭芥子（日本のからし）として現れるとされる。日本へは十六世紀にポルトガル船が運んだという説と、文禄・慶長の役で持ち帰られたという説があり、定説はない。日本の伝えは海の向こうの朝鮮を指し、朝鮮の記録は海の向こうの日本を指している。玉蜀黍と、同じ迷い方をしている。"], ["辛みは、味ではなく痛みである", "ナス科トウガラシ属（Capsicum）。トマト・ジャガイモ・ナスと同じ科で、実は液果——つまり果物の仲間の構造をしている。辛み成分のカプサイシン類は種ではなく、種がつく白いすじ（胎座）で作られる。この物質は TRPV1 という受容体に結びつく。TRPV1 はもともと、およそ43℃を超える熱や酸で開く見張り役とされ、だから脳はそれを「熱い・痛い」と読む。舌は実際には少しも傷ついていない。水では流れず、脂やアルコールには溶ける。鳥は哺乳類ほどこれに反応しないとされ、種を噛み砕く哺乳類を遠ざけ、丸のみして遠くへ運ぶ鳥に託しているのだ、と説明されることがある。栽培化された種はおよそ五つで、メキシコ、アンデス、アマゾンと、それぞれ別の場所で人の手に入ったと考えられている。ピーマンやパプリカも同じ Capsicum annuum で、辛みを作れない品種にすぎない。辛さの物差しスコヴィルは、もとは水で薄めて舐め、辛さが消えるまでの倍率で決める方法（1912年）だった。いまは成分を測って換算するが、同じ品種でも育ち方や実ごとに幅が出る——ピーマンは0、ハバネロは十万を超えるとされる。"], ["五百年で、世界の食卓が塗り替わった", "コロンブス以後、ポルトガルの船が数十年でアフリカ、インド、東南アジア、東アジアへこの実を運んだ。種が小さく、乾かせば軽く、暖かければどこでも育つ。インドのカレー、四川の麻辣、タイのプリック、ハンガリーのパプリカ——いまでは土地の顔になっている辛さは、どれも五百年より新しい。朝鮮半島では、唐辛子を入れた赤いキムチやコチュジャンが広く記されるのは十八世紀以降とされ、それ以前のキムチは赤くない。日本では、七味唐辛子は江戸の薬研堀（やげんぼり）で生まれたと伝えられ、蕎麦とともに広まった。内藤新宿のあたりで作られたものは内藤唐辛子と呼ばれ、鷹の爪は品種の名である。世界じゅうで「昔からの味」と思われているものの多くが、大西洋を渡った一つの実のあとに来ている。"]], "invite": "乾いた唐辛子を一本、縦に割ってみる。辛みを作っているのは種ではなく、種がくっついている白いすじのほう。触れた指は水では落ちないので、油か石けんで洗う。（触れた手で、目や口のまわりをこすらない。）", "works": [{"t": "art", "f": "tougarashi_a1.jpg", "date": "紀元前180年〜500年（ナスカ）", "place": "ペルー南海岸", "title": "唐辛子を抽象化した文様の小鉢（Miniature Flared Bowl Depicting Abstract Peppers with Decorative Motifs）", "artist": "作者不詳（ナスカ）", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/4741", "note": "高さ10センチ、口径19センチほどの鉢。濃い地に、白と橙の波形の帯が斜めに走り、そのあいだに、先のとがった細長い形が置かれている。上の端から短い柄が、くるりと曲がって出ている——実の形だけを抜き出して、輪郭にしたように見える。館の題はこれを「抽象化された唐辛子」と呼び、館の分類では「ミニチュア」の器にあたる。器そのものに文字はないので、この形を唐辛子と読んでいるのは美術館の同定である。その読みが正しいなら、二千年前の南海岸で、この実はもう文様になるくらい身近だったことになる。"}, {"t": "art", "f": "tougarashi_a2.jpg", "date": "600〜900年（マヤ古典期後期）", "place": "メソアメリカ・ネバフ地域（現グアテマラ）", "title": "戦いの場面の器（Vessel with Battle Scene）", "artist": "作者不詳（マヤ）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2012.32", "note": "高さ17センチ、径15センチほどの円筒形。縁をマヤ文字の帯がめぐり、その下に、ジャガーの毛皮の衣をつけた人物、槍、装いを剥がれた者が並ぶ。館の説明では、戦のあとに捕虜を差し出す場面で、縁の文字はこの器がカカオの飲みもののためのものだと記しているという。唐辛子は、どこにも描かれていない。館の「Did you know」がこう書いている——マヤの人びとは、カカオの豆と唐辛子で作った飲みものを、こういう器で飲んだ。絵をいくら探しても見つからないものが、器の中身のほうにいる。館の記載でも年代は「600–900年」と「7〜10世紀」に揺れている。"}, {"t": "art", "f": "tougarashi_a3.jpg", "date": "1450〜1532年（インカ）", "place": "ペルー・クスコ近郊か", "title": "スチェという魚と唐辛子の小皿（Minitature Tray Depicting Suche Fish and Peppers）", "artist": "作者不詳（インカ）", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/91503", "note": "長さ24センチ、高さ8センチほどの浅い楕円の皿。縁に細かい三角の鋸歯がめぐり、内側では、縞のある魚が四匹、向きをばらばらにして泳ぐ。そのあいだに散らばる、黒い楕円の点と、小さな赤いとがった形——この赤いほうを、館の題は唐辛子と呼ぶ。片端からは太い柄が斜めに立ち上がり、その先は平たい円盤になって放射状の線が刻まれている。反対側の縁には小さな突起が二つ。館の分類語には「供物」があり、ミニチュアの器として扱われている。suche はアンデスの湖にすむ魚の名として知られる。館の題名は Minitature と綴りを誤ったまま登録されており、産地欄も「クスコ近郊か」と留保つき。魚と唐辛子が一皿に並ぶのを、次に置く一六〇九年の記述と重ねて読みたくなるが、それはこちら側の読みである。"}, {"t": "art", "f": "tougarashi_a4.jpg", "date": "1608年", "place": "フランス", "title": "唐辛子の株（Pepper Plant with Geometric Border, folio 46 verso／『花の図譜』より）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1963.594.46.b", "note": "羊皮紙に水彩とインク、銀と金。紙面は31×20センチほどで、一冊に綴じられた花の図譜の、四十六葉目の裏にあたる。一本の株に、緑の実と、橙に染まりかけた実と、真っ赤な実が同時についている——熟していく順番が、一枚のなかに畳まれている。丸くずんぐりしたものと、細長く先のとがったものが混じり、葉のあいだには白い小さな花が二つ開いている。左と上下の縁には銀の菱形の帯。館の題は「Pepper Plant」で、どの種かまでは書いていない。一六〇八年は、この実が大西洋を渡ってから百十数年。当時のヨーロッパの本草家は、これをインドから来た胡椒の類だと考えていたとされる。"}, {"t": "bun", "date": "1609年", "place": "ペルー／リスボン刊", "title": "『インカ皇統記』第一部・「ムリの木と唐辛子について」の章", "author": "インカ・ガルシラーソ・デ・ラ・ベガ", "quote": "Los de mi tierra son tan amigos del uchu, que no comerán sin él", "src": "es.wikisource『Comentarios reales (Primera parte)』（アンソロジー）第XXVII章「DEL ÁRBOL MULLI Y DEL PIMIENTO」の全文で照合。同ページの章番号はこのアンソロジーの通し番号で、原著の巻・章立てとは対応しない。原著は1609年リスボン刊・著作権満了", "note": "「私の土地の者は uchu が好きで、それなしには食べない」。著者はインカの王族の母とスペイン人の父を持ち、クスコで育った人である。この一節の前後で、彼は同じ実を三つの言葉で呼び分けている——ケチュア語の uchu、スペイン人の言う「インディアスの胡椒」、そして「カリブの島々の言葉だ」と断ったうえでの axi。太くて丸いものを rocot uchu、細長いものは王家とその一族が使うもの、さくらんぼほどの小さくて丸いものは比べものにならないほど辛い、と書き分ける。そして、うますぎるので厳しい断食のあいだは食べることが禁じられていた、とも書く。小さくて丸い種類の名は、この版の本文では chinchi ullu と綴られており、他の版で見る chinchi uchu と食い違っている。"}, {"t": "art", "f": "tougarashi_a5.jpg", "date": "18世紀後半〜19世紀（清）", "place": "中国・景徳鎮", "title": "唐辛子の形の嗅ぎたばこ入れ（Snuff bottle in the shape of a hot pepper）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/41649", "note": "高さ7センチ。磁器に赤い上絵をかけて実の肌をつくり、へたにあたるところだけ緑のガラスで作ってある——それが栓で、抜くと口が開く。景徳鎮の焼きもの。中に入れるのは粉にした嗅ぎたばこで、唐辛子とは関係がない。実の形が、持ちものの形として借りられているだけである。美術館がこの品につけている分類語は「Vegetables（野菜）」。中国の記録に唐辛子が現れるのは十六世紀の終わりごろとされ、はじめは食べるものとしてより、庭に植える草として書かれた、と説明されることが多い。四川の料理の芯になるのは、それよりずっとあとのこととされる。"}, {"t": "bun", "date": "1908年（明治41）", "place": "日本・東京", "title": "三四郎 五", "author": "夏目漱石", "quote": "屋根の下が一面に赤い。近寄って見ると、唐辛子を干したのであった", "src": "『三四郎』第五章。本文はウィキソース『三四郎』の全文で照合（初出は1908年・明治41年の新聞連載）", "note": "団子坂の菊人形を見た帰り、気分をわるくした美禰子を連れて、三四郎が小川のふちまで来る場面。向こうの藁屋根の下が一面に赤いので、近づいてみると干した唐辛子だった。美禰子はそれが唐辛子だと見分けのつくところまで来て立ちどまり、「美しいこと」と言って草に腰をおろす。このすぐあとに、彼女は「迷える子（ストレイ・シープ）」とつぶやく。辛さの話は一言も出てこない。ここで唐辛子は、秋の日に干されている赤い面積でしかない——渡来から三百年あまりで、この実は日本の風景の色になっていた。"}, {"t": "photo", "f": "tougarashi_p1.jpg", "date": "いま（2010年）", "place": "韓国（撮影地の記載なし）", "title": "干した英陽（ヨンヤン）の唐辛子（写真）", "artist": "Eugene Kim", "museum": "Wikimedia Commons", "lic": "CC BY 2.5", "url": "https://commons.wikimedia.org/wiki/File:Yeongyang-gochu_(dried).jpg", "note": "織り袋の口が開いて、乾いた実がぎっしり詰まっている。深い赤から黒みを帯びた臙脂まで色に幅があり、表面は縮んで皺が寄り、緑がかった柄とへたが残ったまま。Commons の説明は「乾いた英陽の唐辛子」で、英陽（慶尚北道）は韓国の唐辛子の産地として知られる。朝鮮半島の記録に唐辛子が現れるのは十七世紀の初めごろが最初とされ、そこでは南蛮椒、あるいは倭芥子——海の向こうから来たものとして書かれている。いま「韓国の味」と呼ばれているものの芯にあるのは、その、渡ってきた実である。撮影は2010年10月19日。"}]}, {"id": "negi", "no": "第十一景", "kind": "yasai", "name": "葱", "yomi": "ねぎ", "en": "Welsh onion, onion and leek — the genus Allium", "rep": "negi_a3.jpg", "lead": "白いところは根ではなく、土をかけて日を遮った葉である。中央アジアのあたりが出どころとされ、東へも西へも運ばれた。四千年前のメソポタミアの粘土板には、もう配る量として書かれている。", "layers": [["白いところは、根ではない", "ヒガンバナ科（かつてはユリ科に置かれた）ネギ属の草。根深葱の白い部分は根ではなく、葉のつけ根が筒になって幾重にも重なったところ——葉鞘（ようしょう）である。葉鞘と葉身が重なって茎のように見えるので、偽茎（ぎけい）と呼ぶ。ほんとうの茎は地面のすぐ下で平たい円盤に縮まっていて、そこから下へ細い根が出る。ネギは玉をつくらない。玉をつくるタマネギのほうも中身は同じで、肥った葉のつけ根が幾重にも巻いたもの——外側の茶色い薄皮は、枯れた葉である。ネギの葉が中空なのは種の性質で、学名の fistulosum は「中空の」の意。切ると目にしみるのは、組織が壊れて酵素がはたらき、揮発する成分ができるためとされる。"], ["出どころは、はっきりしない", "ネギ属（Allium）は認められる種がおよそ千にのぼるとされる大きな属で、台所にいる顔ぶれのうち、タマネギとネギは野生の姿がはっきりしない。タマネギ（A. cepa）は栽培のかたちでしか知られておらず、いちばん近い野生種は中央アジアとイランにあるとされる。ネギ（A. fistulosum）も、原産は中国西部から中央アジア・アルタイのあたりといわれるだけで、野生の姿は分かっていない。リーキ（Allium ampeloprasum）は別の種で、南ヨーロッパ・西アジア・北アフリカ——地中海のまわりが本拠とされる。こちらは野生のもの（ワイルドリーク）が地中海のまわりに広く分布していて、野生の姿が分かっている。エジプトでは前二千年紀の遺跡から乾いたリーキが出土し、メソポタミアでも同じころ栽培されていたことが文書から分かるという。リーキはいまウェールズの国の象徴のひとつで、聖デイヴィッドの日に身につける。なお英語でネギを Welsh onion と呼ぶが、この Welsh はウェールズではなく「外来の」を指す古い用法によるとされる。名前のほうが、また出どころを取り違えている。"], ["土をかけて、白くする", "根深葱の白いところは、育つあいだ土に埋まっていたところである。畑では葱の伸びに合わせて何度も土を寄せ、葉鞘を土の中へ隠していく。日が当たらなければ葉緑素はつくられないので、埋まった分だけ白いまま伸びる——白い長さは、かけた土の高さで決まる（どこまで伸ばせるかは品種によって違う）。日本では、東で白いところを食べる根深葱（千住・深谷・下仁田）、西で青いところを食べる葉葱（九条）が育ってきた、と言われることが多い（この差は薄れつつあるともいわれる）。同じ種の草を、片方は土に埋め、片方は日に当てて育てる。八百屋に並ぶ一本の葱は、どこまで土がかかっていたかの記録でもある。"]], "invite": "根深ねぎ（白ねぎ）の白いところを、輪切りにしてみる。切り口に、幾重もの輪が見える——この輪の一枚一枚が葉のつけ根（葉鞘）で、白いところが根ではないことは、ここで見て取れる。", "works": [{"t": "art", "f": "negi_a1.jpg", "date": "前2028年ごろ", "place": "メソポタミア（現イラク）・ウンマ", "title": "麦酒・パン・油・玉葱の配給を記した粘土板（Cuneiform tablet: record of rations of beer, bread, oil, and onions for messengers）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/327069", "note": "館の記載＝新シュメール期・ウル第三王朝、メソポタミアのウンマ（現ジョカ）、粘土、3 × 2.8 × 1.2 cm。指先に載る大きさである。館の題は、この板を「使者たちに配る麦酒・パン・油・玉葱の量を記した記録」と呼ぶ。写真は灰色の地に置かれた一枚で、横の罫線で区切られた行に楔形の字がすき間なく詰まり、縁のきわまで埋まっている。楔形文字を読むことは当方にはできないので、何が書いてあるかは館の題に依った。四千年前の帳簿に、玉葱が、物語でも捧げものでもなく、配る量として出てくる。"}, {"t": "bun", "date": "前430年ごろ", "place": "ギリシャ／エジプト", "title": "『歴史』第二巻・一二五", "author": "ヘロドトス", "quote": "σεσήμανται δὲ διὰ γραμμάτων Αἰγυπτίων ἐν τῇ πυραμίδι ὅσα ἔς τε συρμαίην καὶ κρόμμυα καὶ σκόροδα ἀναισιμώθη τοῖσι ἐργαζομένοισι", "src": "『歴史』第二巻125章6節。ギリシャ語本文はギリシャ語版ウィキソース「Ιστορίαι (Ηροδότου)/Ευτέρπη」で照合し、英語版ウィキソース所収のローリンソン訳（George Rawlinson／1812〜1902）『The History of Herodotus』Book 2 の該当箇所（radishes, onions, and garlic … 1600 talents of silver）と突き合わせた。ヘロドトスは前5世紀の人", "note": "「そのピラミッドには、働く者たちにスュルマイエー（訳の定まらない語で、大根のたぐいと訳されることが多い）と玉葱と大蒜（にんにく）がどれだけ費やされたかが、エジプトの文字で記されている」。続けてヘロドトスは、銀千六百タラントンだった、と数字まで書く。ただしその数字の出どころは、本人が読んだ碑文ではない。原文には「通訳が私にその文字を読んで聞かせて言うには、私がよく憶えているかぎり」と断りがある——つまり伝聞である。碑文が実在したかどうかは、この一節からは決められない。決められるのは、前五世紀のギリシャ人がピラミッドの話をするときに、石でも王でもなく、玉葱と大蒜の勘定を持ち出した、ということだけである。"}, {"t": "art", "f": "negi_a2.jpg", "date": "1602〜04年", "place": "ムガル朝インド・アラーハーバード", "title": "荒野のイエスに食べ物を運ぶ天使たち（Angels bring food to Jesus in the wilderness）──『聖性の鑑（Mir’at al-quds）』folio 55 recto", "artist": "ムハンマド・シャリーフ（Muhammad Sharif・1600年ごろ活動）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2005.145.55.a", "note": "館の解説は、四十日の断食を終えたイエスのもとへ五人の天使が天から食べ物を運んだ場面だとし、その品を「パン、切りやすいように小刀を添えた瓜、生の葱（fresh leeks）、香りのよい米料理とカレーらしきもの、葡萄酒の杯」と挙げる。数えると天使はたしかに五人で、うち一人は衣を着けず羽だけをまとう（館の記載どおり）。その羽の天使は、緑の丸い瓜に白い小刀を刺したものを抱えている。雲の中を頭から降りてくる紫の衣の天使は、白い浅い皿に濃い緑の細長い束を載せている——館のいう葱をここに読むのはこちら側で、館はどの器に何が載っているかまでは書いていない。画面の下、草の上には金の椀と皿、盛り上げたパン、緑の丸い瓜、開いた本が並ぶ。"}, {"t": "art", "f": "negi_a3.jpg", "date": "1608年", "place": "フランス", "title": "二つの玉葱と一つのキャベツ、幾何文の縁飾り（Two Onions and a Cabbage with Geometric Border）──『花譜（Florilegium）』folio 45 verso", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1963.594.45.b", "note": "羊皮紙に水彩とインク、銀と金。赤と白の幾何文の縁のなかに、三つの株が根まで見えるように並ぶ。左は扁球形の赤い鱗茎から緑の筒状の葉が扇に開き、鱗茎の首のところに、葉が球へ移り変わる薄い輪が一本、描き分けてある。右は細長い白い鱗茎で、葉はやはり筒。真ん中はキャベツで、長い茎の下に褐色の密な塊がついている。左右の玉葱には細い根が幾筋も束になって描かれ、真ん中のキャベツだけ根もとが塊のままである。館の記載は題と技法だけで、解説文はない。この帖の隣の葉（folio 46 verso）の唐辛子は、《やさい百景》の唐辛子の景に入れてある。"}, {"t": "art", "f": "negi_a4.jpg", "date": "1734年ごろ", "place": "フランス", "title": "葱と魚と卵のある台所道具（Kitchen Utensils with Leeks, Fish, and Eggs）", "artist": "ジャン・シメオン・シャルダン", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1980.37", "note": "銅の鍋に蓋、黒い深鉢、白い布、白い卵が二つ、石の乳鉢と杵。台の左の端に葱（リーキ）が根つきのまま横たわり（館の題は複数形）、白い根の束が縁から垂れている。根の上に白い葉鞘が続き、そこから灰緑の葉が斜めに上がって暗がりへ消える。布の下からは灰青の平たいものがのぞく——館の題はこれを魚と呼ぶ。館の解説は、シャルダンが1730年ごろから台所道具の小さな静物を描きはじめ、同じ道具を少しずつ置き換えながら釣り合いを取ったこと、いちばん粗末なものの中に隠れた詩を見つけた画家であることを説く。葱は主役ではない。台所の端に、白いところを外へ向けて寝かせてある。"}, {"t": "art", "f": "negi_a5.jpg", "date": "1810年代", "place": "日本（江戸）", "title": "摺物帖『春雨集』巻一 ── 鴨と葱（Spring Rain Collection (Harusame shū), vol. 1: Duck and Scallions）", "artist": "柳々居辰斎", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/54811", "note": "摺物＝私家版の版画を集めた帖の一枚で、館の題は「鴨と葱」。横たわった鴨は頭が黒く、その黒の上ぎわ（頭頂から後頭）に黄がひと刷け入り、嘴は淡い黄緑、目は橙の輪で、胸から腹が白く、風切りは灰青、足は橙。その背から青い葉が扇のように何本も右へ伸びる。鴨の頭の左には、色を置かずに紙を凹ませただけの細長い白い形がある——葱の白いところをここに読むのはこちら側だが、館の題が葱を数えていることとは合う。右下に淡い緑の小さな塊が二つ。左半分は狂歌で埋まっている。14.3 × 19.2 cm。葱が日本へ来たのは奈良時代といわれ、『日本書紀』仁賢天皇六年（493年）九月の「秋葱」が最古の記録とされる（当方は原典に当たれていない）。「鴨が葱を背負って来る」という言い方もあるが、この一枚がその言い方とつながるのかどうかは、絵からも館の記載からも決められない。"}, {"t": "photo", "f": "negi_p1.jpg", "date": "いま（2017年）", "place": "ウズベキスタン・フェルガナ", "title": "市場に積まれた玉葱（写真）", "author": "Shuhrataxmedov", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File:Onions_in_the_Fergana_market_(Uzbekistan).jpg", "note": "撮影者の説明はロシア語で「フェルガナ州（ウズベキスタン）の市場の葱（лук）」。淡い黄の皮の玉葱が台の上に几帳面に積み上げられ、その多くが根のほうを上にして置かれている。乾いた根が茶色の房になって放射し、皮には縦の繊維の筋と褐色の染みが残る。奥に赤いかご。ここフェルガナのある中央アジアは、ネギ属の野生の親類が集まっている土地とされるところの一つである——出どころのはっきりしない作物が、その出どころのあたりで、いま積まれている。"}]}, {"id": "ninniku", "no": "第十二景", "kind": "yasai", "name": "大蒜", "yomi": "にんにく", "en": "Garlic — one bulb that splits into cloves, and travels by human hands", "rep": "ninniku_a3.jpg", "lead": "一つの球が、いくつもの片に分かれる。種はほとんどできず、分かれた片がそのまま次の株になる——数千年、人の手で株分けされて運ばれてきた野菜。においのせいで、門の外に置かれてもきた。", "layers": [["一つの球が、いくつもの片に分かれる", "ヒガンバナ科ネギ属（Allium sativum）。分類は動いていて、古い本ではユリ科、その後ネギ科ともされた。食べているのは根ではない。球の底にある平たい円盤が茎で、そこからひげ根が下り、上には片（鱗片）が放射状に並ぶ。片の数は品種で違い、数個から二十個ほど。一片は、芽と、それを包んで厚くなった葉のセットになっている。栽培されている大蒜は、花茎を伸ばしても種子をほとんど作らないとされ、増やし方は片を一つずつ植えること——つまり株分けである。だから畑の一列は、遺伝的にほとんど同じ株の並びになる。花茎（蒜薹／にんにくの芽）の先には、花のかわりに小さな珠芽がつくことがあり、それを植えても増える。"], ["名前が、西のほうを指している", "原産は中央アジアのあたりとされる。中国では、もとからあった小さいほうを「蒜（小蒜）」、あとから来た大きいほうを「葫（大蒜）」と呼び分けた。『本草綱目』（1596年刊）は古い書物を引いて、「胡國に蒜あり、十子一株、名づけて胡蒜、俗に大蒜という」と記す——十の子（こ）が一株になっている、という描き方のあとに、胡（西の外国）の一字が名として残った。張騫が西域から持ち帰ったという伝えも繰り返し引かれるが、それを載せる書物は張騫より四百年ほどのちのもので、確かなことは分からない。中国よりずっと西のエジプトでは、もっと古い石碑や墓の中に、供物として積まれた野菜が先に現れている。名前が向きを持っているのは、あくまで中国から見た話である。"], ["においで、線が引かれた", "においの強いネギ属などをまとめて「五葷（ごくん）／五辛」と呼び、修行の場では避けられてきた。『本草綱目』は、その数え方が一つでないことを書き留めている——練形家は小蒜・大蒜・韭・芸薹・胡荽、道家は韭・薤・蒜・芸薹・胡荽、仏家は大蒜・小蒜・興渠・慈葱・茖葱。並びは違っても、どれも「辛熏の物」でくくられている。日本では、禅寺の門前に戒壇石が立ち、「不許葷酒入山門」——葷酒、山門に入るを許さず、と刻まれた。石の文句は、食べるな、ではなく、においを連れて門をくぐるな、と読める。同じ球根が、片方では故郷の味として惜しまれ（『民数記』）、片方では境内の外に置かれた。"]], "invite": "大蒜をひっくり返して、底の平たい円盤を見てみる。片はその円盤から放射状に出ていて、ひげ根の跡もそこにある——円盤が茎で、食べているふくらみは、厚くなった葉。", "works": [{"t": "art", "f": "ninniku_a1.jpg", "date": "前1956〜前1877年ごろ（中王国・第12王朝初め）", "place": "エジプト（おそらくテーベ＝現ルクソール）", "title": "アメンエムハトとヘメトの石碑（Stela of Amenemhat and Hemet）", "artist": "作者不詳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/127859", "note": "石灰岩を浮き彫りと沈み彫りにし、黒・茶・緑・黄・白の絵具で彩色したもの（館の記載）。31×42センチほど。左に、黄色い肌の妻ヘメトが長い黒髪と白い衣で立ち、赤茶の肌の夫アメンエムハトの肩に手をかけて、白と緑の花を顔のそばへ差し出す。二人の前には供物の台が二つ。黄色い縦筋の入ったパンの束、赤い肉のかたまり、背の高い壺、そして白いふくらみから細長い緑の葉がひろがるもの。館がこの石碑につけた主題語には「野菜（vegetables）」が入っているが、どの野菜かは書かれていない。大蒜とも、どこにも書かれていない。見えているのは、食べものを死んだあとまで積んでおく、という考え方のほうである。"}, {"t": "art", "f": "ninniku_a2.jpg", "date": "前1491〜前1458年ごろ（新王国・第18王朝）", "place": "エジプト・上エジプト テーベ", "title": "23個の塊茎（23 Plant Tubers）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/549066", "note": "館の分類は「食べもの、塊茎（23個）」。素材の欄にはただ「塊茎」とあり、寸法は「一つの長さ2.8センチ」だけが書かれている。テーベの発掘（1935〜36年）で出たもの。写真では、蓋を外した編み籠に、黒く縮んだものが山になって入っている（館の記載も出土位置を「burial 2, in basket」＝籠の中と書いている）。塊茎（茎が太った芋の類）と鱗茎（葉が重なった球）は別の器官で、大蒜は鱗茎のほうである。だから、館の記載どおりなら、これは大蒜ではない。ただ、三千五百年前の食べものが今日まで残っているのは、籠ごと墓に納められたからである。"}, {"t": "bun", "date": "前6〜前5世紀ごろ（現在の形にまとまった時期とされる）", "place": "レヴァント", "title": "『民数記』11章5節（ヘブライ語聖書）", "author": "作者不詳（ヘブライ語聖書）", "quote": "אֵת הַקִּשֻּׁאִים וְאֵת הָאֲבַטִּחִים וְאֶת הֶחָצִיר וְאֶת הַבְּצָלִים וְאֶת הַשּׁוּמִים", "src": "ヘブライ語版ウィキソース「במדבר יא/ניקוד」（母音符号つきの本文）第5節で照合 <https://he.wikisource.org/wiki/במדבר_יא/ניקוד>。英訳は英語版ウィキソース所収の欽定訳（King James Version・1611年刊・著作権満了）「Bible (King James)/Numbers」11:5 と突き合わせた", "note": "荒野の場面。エジプトを出た人びとが泣いて言う——「エジプトでただで食べていた魚を、われわれは覚えている。胡瓜も、瓜も、葱の類も、玉葱も、大蒜も」。ヘブライ語で大蒜は שׁוּם（シューム）、その複数形がここに立っている。三番目の הֶחָצִיר はもともと「草」を意味する語で、欽定訳は leeks（葱の類）と訳した。並んでいるのは、どれも畑の、しかも土の中か地ぎわのものばかりである。ここで大蒜は、においの悪者としてではなく、置いてきたものとして書かれている。強いにおいの球根が、故郷の味の側にいる。"}, {"t": "bun", "date": "6世紀（後魏）", "place": "中国", "title": "『齊民要術』巻三「種蒜第十九」", "author": "賈思勰", "quote": "收條中子種者，一年為獨瓣；種二年者，則成大蒜，科皆如拳", "src": "中国語版ウィキソース『齊民要術 (四庫全書本)/卷03』「種蒜第十九」の本文で照合 <https://zh.wikisource.org/wiki/齊民要術_(四庫全書本)/卷03>。四庫全書本には句読点がないので、読みやすさのために区切りを入れた。賈思勰は後魏の人で、書物の成立は530〜540年代とされる", "note": "「花茎の先につく子（珠芽）を採って植えると、一年目はひとかけ（獨瓣）のままで、二年目に大蒜になる。かたまりはどれも拳ほどになる」。千五百年前の農書が、種子をほとんど作らないこの野菜の増やし方を、二年がかりの手順として書いている。同じ章は、九月の初めに植えること、葉が黄ばんだころに取り出し、編んで屋下の風の涼しいところに架けて吊るすことも書く。注にはこうある——并州には大蒜がなく、朝歌から種を取ってきても、一年で「百子蒜」、片が珠芽ほど細かい蒜に戻ってしまう。書いた人はそれを「みな自分の目で見た」と言い、理由を「土地の違いだろう（盖土地之異者也）」と置いている。同じ球でも、置かれた土地で分かれ方が変わる。"}, {"t": "art", "f": "ninniku_a3.jpg", "date": "1736〜95年（清・乾隆）", "place": "中国・景徳鎮", "title": "蒜頭瓶（清乾隆 景德鎮窯月白釉暗花蒜頭瓶／Bottle vase）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/51041", "note": "高さ15.2センチ。淡い水色の釉（月白釉／clair de lune）をかけた磁器で、丸い胴から細い首が立ち、その先が球のようにふくらんで口になる。ふくらみには弧の彫りが薄く入り、いくつかの丸い区画に分かれて見える。胴には釉の下に、渦を巻く唐草のような彫り（暗花）がうっすらと浮く。館の英語の題は「Bottle vase（瓶）」としか言わない。ところが館が公開しているデータでは題が二段になっていて、中国語のほうは「清乾隆　景德鎮窯月白釉暗花蒜頭瓶」——蒜頭瓶、にんにくの頭の瓶、と呼んでいる。名づけたのは形である。口のふくらみが、皮に包まれた球の輪郭をそのままなぞっている。"}, {"t": "art", "f": "ninniku_a4.jpg", "date": "1809〜17年", "place": "スペイン・マドリード", "title": "にんにくと玉葱（『マドリードの呼び売り』第2図／Plate 2: four street vendors from Madrid selling garlic and onions, cucumbers, fine crockery, oil, from 'Los Gritos de Madrid'）", "artist": "ミゲル・ガンボリーノ（Miguel Gamborino）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/856578", "note": "手彩色の銅版画。30×20センチの紙に、四人の物売りが一人ずつ、影の落ちた小さな地面の上に立っている。左上の一人の下に「Ajos y Cebollas」——にんにくと玉葱。白い頭巾、茶の上着、黄緑の前掛け、赤いスカート。左手を腰にあて、右手を上げて、編んだ球の束を肩の高さにぶら下げている。口が開いている。連作の題が『Los Gritos de Madrid（マドリードの叫び＝呼び売り）』なのだから、開いた口は声である。ほかの三人は胡瓜売り、焼きもの売り、油売り。にんにくは、店の台の上にではなく、通りを歩いてくるものでもあった。編めば、まとめて提げられる。『齊民要術』は編んで軒下に架けよと書く。"}, {"t": "photo", "f": "ninniku_p1.jpg", "date": "いま（2007年）", "place": "韓国・全羅南道高興郡", "title": "ガードレールで干している大蒜（写真）", "artist": "Steve46814", "museum": "Wikimedia Commons", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File:Korea-Goheunggun-Garlic_harvest_4207-06a.jpg", "note": "道路わきのガードレールに、掘り上げた大蒜が束のまま何束も掛けてある。葉と茎は枯れて藁色になり、その下に白い球がぶら下がる。向こうには瓦屋根の家と刈り込まれた生垣、右手に緑の畑。Commons の説明は「全羅南道・高興郡の田舎で、収穫したての大蒜を干しているところ」、日付欄は2007年10月18日。『齊民要術』が「葉が黄ばんだら取り出し、編んで、屋下の風の涼しいところに架ける」と書いてから、千五百年ほど。掛ける場所も日ざしも違うが、束のまま吊るして乾かすところは変わらない。"}]}, {"id": "tomato", "no": "第十三景", "kind": "yasai", "name": "トマト", "yomi": "とまと", "en": "Tomato — an Andean berry, domesticated in Mesoamerica; eaten in the south of Europe from the first, but kept in the flower bed in the north", "rep": "tomato_a2.jpg", "lead": "ナス科の液果。アンデスに野生の親類がいて、メソアメリカで作物になり、十六世紀にヨーロッパへ渡ったあとも、北のヨーロッパでは長く庭で眺められるだけだった。イタリアの赤も、インドの赤も、この実が来てからの色である。", "layers": [["切ると、部屋がある", "ナス科の Solanum lycopersicum。ジャガイモ・ナス・唐辛子と同じ科で、実は液果（えきか）——子房がまるごと肉になり、種を果肉の中に抱えたままの果実である。輪切りにすると、白い芯から壁が放射状に伸び、種のつまった部屋がいくつも並ぶ。ミニトマトなら二つ、大玉なら十近くに分かれることもある。だから植物学の側では、トマトは果実だ。それでも台所では野菜として扱われる。1893年、アメリカの最高裁は関税をめぐる裁判で、植物学の分類ではなく日々の言葉づかいを根拠に、トマトは野菜だと判じた。果物か野菜かは、栽培と調理と商いの区分であって、植物の側の区分ではない。花は黄色く、葯（やく）が寄り集まって筒をつくり、それぞれの葯は筒の内側に向いた縦の裂け目から花粉を出す。花粉は筒の中にたまるので、揺すらないと外へ出てこない。だから温室では、羽は動かさずに胸の筋を震わせて花を揺するマルハナバチを放して受粉させる。"], ["毒草の顔をして、庭にいた", "野生の近縁種は、アンデスの西斜面から海岸沿いにかけて小粒の実をつける草で、作物になったのはメソアメリカ（いまのメキシコ）だと考えられている。ナワトル語では xitomatl（シトマトル）と呼ばれ、そこからスペイン語の tomate、英語の tomato が出た。十六世紀にヨーロッパへ渡ると、名前は土地ごとに割れる。ラテン語で Pomum aureum（黄金の林檎）と Poma amoris（愛の林檎）、イタリア語の pomodoro は pomo d'oro から、フランス語は pomme d'amour、英語では love apple。ところが北のヨーロッパでは、長く食べものにならなかった。見慣れないナス科の草で、ベラドンナやヒヨスと同じ顔をしていたからだ、と説明される。日本へは江戸期に伝わり「唐柿」「唐なすび」などと呼ばれたとされる。食べるのは明治以降とされる。"], ["土地の味になったのは、ついこのあいだ", "イタリアで書かれた最初のトマトソースの作り方は、1692年ナポリのアントニオ・ラティーニの料理書にある「スペイン風のトマトのソース」だとされる。渡来から百五十年ほど。乾麺にトマトを合わせるのが当たり前になるのはさらにあとで、1891年のアルトゥージの家庭料理書では、トマトはもう「どこにでも入るもの」のたとえに使われている。インドへはポルトガル船が運んだとされ、いまでは中国につぐ生産国とされる。土地の顔になっている赤は、どこでも、その土地でいちばん古い色ではない。世界の台所がこの実で塗り替わるのに、五百年もかかっていない。"]], "invite": "トマトを、へたの側からではなく横に倒して輪切りにしてみる。種の入った部屋がいくつあるか数えて、大玉とミニトマトで比べてみる。", "works": [{"t": "bun", "date": "1597年", "place": "イギリス・ロンドン", "title": "『本草書、または植物の一般誌（The Herball, or Generall Historie of Plantes）』第二之書 第55章「愛の林檎について（Of apples of Loue）」", "author": "ジョン・ジェラード", "quote": "the whole plant is of a ranke and stinking sauour", "src": "1597年ロンドン刊（John Norton 印行）の初版。ミズーリ植物園蔵本のスキャン（Internet Archive の mobot31753000817749）の275頁・276頁を画像で開いて読み、当該の行を確かめた。綴りは原文のまま（長い s は現代字に直した）", "note": "「この草はぜんぶ、きつい、いやな匂いがする」。同じ頁でジェラードは実を「がちょうの卵ほどの大きさ」「明るく光る赤」「畝が寄って、あちこちに膨らんでいる」と書き、「愛の林檎はスペイン、イタリア、そういう暑い国に育つ。私はそこから種をもらって庭で育てている」と続ける。そのあとに名前を並べる——ラテン語で Pomum Aureum、Poma Amoris、Lycopertium（この綴りのまま印刷されている）、英語で apples of Loue と golden apples、フランス語で Pommes d'amours。次の頁では、あちらでは油と酢と胡椒を混ぜて肉のソースにする、「われわれ寒い国の者が芥子（マスタード）を使うように」と書く。食べる話は、ぜんぶ「あちら」の話として書かれている。"}, {"t": "art", "f": "tomato_a2.jpg", "date": "1737年", "place": "イギリス・ロンドン", "title": "愛の林檎（Love Apple ／ Amoris Pomum）── 『A Curious Herbal』第133図", "artist": "エリザベス・ブラックウェル", "museum": "Wikimedia Commons（Biodiversity Heritage Library のスキャン）", "lic": "パブリックドメイン", "url": "https://commons.wikimedia.org/wiki/File:A_curious_herbal_(Plate_133)_BHL296453.jpg", "note": "銅版に手彩色。右上に「Plate 133」。一株がまるごと立ち、黄色い星形の花が咲き、右には緑の未熟な実がふたつ重なって垂れ、その陰にもうひとつ小さいのが見える。左下には熟した赤い実、その上に横に切った実の断面が置かれ、白い芯のまわりに種を抱えた部屋が八つほど数えられる。下の欄は「1. Flower／2. Ripe Fruit／3. Fruit open／4. Seed」と番号を振り、左に「Eliz. Blackwell delin. sculp. et Pinx.」——描き、彫り、彩色までひとりでやった、と署名が言っている。題は英語で Love Apple、ラテン語で Amoris Pomum。『A Curious Herbal』は薬屋のための図譜として1737〜39年に分冊で出た本で、台所の本ではない。ジェラードから百四十年たっても、この実はまだ図譜の側にいる。"}, {"t": "art", "f": "tomato_a3.jpg", "date": "1765年ごろ", "place": "インド（ムガル・ムルシダーバードまたはラクナウ）", "title": "花咲くマリーゴールド（Flowering Marigold）── 画帖の一葉の裏", "artist": "フンハル二世の様式（Style of Hunhar II）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2013.351.b", "note": "紙にガム・テンペラと金。頁は33.1×24.9センチ。橙の八重のマリーゴールドが一株から扇のように立ち、金の唐草の縁取りにも小さな同じ花が並ぶ。トマトはどこにも描かれていない。館の解説がこう書いている——1500年代から1600年代にかけて盛んになったポルトガルとの交易が、南米の領土から多くの植物をインドへ運んだ。じゃがいも、トマト、そしてマリーゴールドがその例で、どれもインドの日々の暮らしの定番になった、と。ただし三つの出どころは一つではない。じゃがいもはアンデス、マリーゴールドとトマトはメソアメリカ（いまのメキシコ）が作物としての故郷とされる。館の一行は、そこをまとめて「南米」と書いている。絵になっているのは、同じ船で来た三つのうち、花のほうである。この葉は両面に絵があり、表は〈森のはずれで川を楽しむ女たち〉。館は表裏とも「フンハル二世の様式」とする。"}, {"t": "art", "f": "tomato_a4.jpg", "date": "1828年", "place": "カリブ海・アンティル諸島", "title": "畝のあるトマト（TOMATE À CÔTES）── 『アンティル諸島の薬用植物誌（Flore médicale des Antilles）』第405図", "artist": "J・テオドール・デクルティ（画）／ペレ（版）", "museum": "Wikimedia Commons（Biodiversity Heritage Library のスキャン）", "lic": "パブリックドメイン", "url": "https://commons.wikimedia.org/wiki/File:Flore_m%C3%A9dicale_des_Antilles,_ou,_Trait%C3%A9_des_plantes_usuelles_(10420969506).jpg", "note": "手彩色の銅版。枠の左上に「102e Liv.」、右上に「Pl. 405」。上半分は株で、毛の密に生えた太い茎、切れ込みの深い葉、黄色い星形の花のひとかたまり、そのそばに緑の小さい実が三つ四つと、橙に染まった実がひとつ。左下には花をひとつだけ大きく描いた図がある。下半分は、大きな実をま上から見た図——九つほどの房に分かれている——と、その切り口で、種を抱えた部屋が芯から分かれて八つほど並ぶ。本の副題は「フランス・イギリス・スペイン・ポルトガルの植民地の、日々使う植物」と言っている（この図は第6巻）。題は「畝のあるトマト」。tomate という語は、ナワトル語からスペイン語を経てフランス語に入ったもの。アメリカ大陸で作物になった実が、大西洋を渡って三百年ほどしてから、こんどはカリブ海の「日々使う植物」のひとつとして、この名で図譜に載っている。"}, {"t": "bun", "date": "1891年（照合は1895年版）", "place": "イタリア・フィレンツェ", "title": "『料理の科学と美味しく食べる技法（La scienza in cucina e l'arte di mangiar bene）』「トマトのソース」の項", "author": "ペッレグリーノ・アルトゥージ", "quote": "il popolo arguto lo aveva battezzato Don Pomodoro per indicare che i pomodori entrano per tutto", "src": "イタリア語版ウィキソースの『Scienza in cucina e l'arte di mangiar bene』所収「Salsa di pomodoro」で引用し、同サイトの校正済みスキャン頁（Pagina:Artusi - La scienza in cucina e l'arte di mangiar bene, Landi, 1895.djvu/100 ＝ 1895年フィレンツェ・Landi 版 80頁）と突き合わせて照合した。初版は1891年。項の番号は版で動き、1895年版では第95番、のちの版では第125番。アルトゥージは1820〜1911年の人", "note": "「機知に富んだ人びとは、その司祭を〈ドン・ポモドーロ〉と名づけた——トマトはどこにでも入る、という意味で」。ロマーニャの町に、何にでも首を突っ込む司祭がいた、という短い話の落ちである。悪い人ではなかったので放っておかれた、と前置きがあり、この渾名が来て、「だからこの実の良いソースは、台所で重宝する」と続く。作り方はごく短い。玉ねぎ四分の一、にんにく一かけ、指の長さのセロリ、バジルの葉数枚とパセリを刻み、油と塩と胡椒で調味し、トマトを七つ八つ割って入れて火にかけ、とろりとしたら漉す。渡来から三百年以上たって、この実はもう、人の渾名に使えるほど当たり前になっていた。"}, {"t": "photo", "f": "tomato_p1.jpg", "date": "いま（2009年）", "place": "インド・チェンナイ（コヤンベードゥ市場）", "title": "コヤンベードゥ市場のトマト（写真）", "artist": "McKay Savage", "museum": "Wikimedia Commons", "lic": "CC BY 2.0", "url": "https://commons.wikimedia.org/wiki/File:India_-_Koyambedu_Market_-_Tomatoes_02_(3987058522).jpg", "note": "青いプラスチックの箱に、赤い実がぎっしり詰まっている。手前の箱には、肩にまだ緑を残した実が混じる。奥にも同じ箱が積んである。Commons の説明は題そのまま「India - Koyambedu Market - Tomatoes 02」だけで、それ以上のことは書かれていない。コヤンベードゥはチェンナイの卸売市場。ムガルの画帖（1765年ごろ）の脇に館が書いた一行——ポルトガル船が運んだ——から二百五十年ほど。インドはいま、中国につぐトマトの生産国とされる。外から来た赤が、ここの色になっている。"}]}, {"id": "shouga", "no": "第十四景", "kind": "yasai", "name": "生姜", "yomi": "しょうが", "en": "Ginger", "rep": "shouga_a4.jpg", "lead": "野生の株が、どこにも見つかっていない。めったに咲かず、実もならない。株を割って植えるほかに増えようのないこの草は、人が運ばなければ一歩も動けない。", "layers": [["掘っているのは、根ではなく茎", "土から掘り出すあの塊は、根ではない。地面のすぐ下を横に這う茎で、根茎（こんけい）という。表面を横向きに走る輪は節の跡で、芽はその節から出る。根はそれとは別に、根茎から下へ細く伸びる。英語の取引では、ひと塊を hands（手）や races と呼ぶ。1911年の『ブリタニカ百科事典』第11版は、この呼び名を「不規則に掌状をした形から」だと説明している。地上に立つのは、葉のついた茎と、花の穂。この二つは同じ株から、別々の柄で立ち上がる。花の穂は松かさに似て、長さおよそ5〜8cm、瓦を重ねたような苞が並び、その苞のあいだに小さな花がひとつずつ入る。同じ項の書き出しは、こうである——「Zingiber officinale の根茎、すなわち地下の茎」。食べているのは、地下にもぐったほうの茎である。"], ["野生が、まだ見つかっていない", "同じ1911年の項に、二つの短い文がある。「この植物はめったに花をつけず、果実は知られていない」。そして「野生の状態では見つからないが、アジアの暖かい地方のものと考えてよい十分な根拠がある」。百年以上たったいまも、野生のショウガが見つかったという話は、本景で当たった範囲には出てこなかった。花が咲いても実がならないなら、種で増えることはできない。だから増やし方は、ふつうひとつだけ——根茎を割り、芽のついた欠片を土に埋める。掘って、運んで、また埋める。この草にとって移動とは、人の手に持たれることだった。同じ項は、この草がアジアから西インド諸島・南アメリカ・西アフリカの熱帯・オーストラリアへ「広がった」と書くが、広がったというより、その全部が誰かの運んだ先である。太平洋の島々でも生姜（Zingiber officinale）が育てられているのは、たぶん同じ理由だろう——ただし、いつ誰が運んだのかまでは、本景では確かめられなかった。"], ["三つの名で、呼び分けられていた", "ローマの博物学者プリニウスは、生姜を「アラビアとトロゴデュティケの畑に育つ、白い根の小さな草」と書いた。トロゴデュティケは紅海のアフリカ側の岸。産地ではなく、通り道である。値段まで書いてあり、1ポンド6デナリウス——同じ章の黒胡椒が4、白胡椒が7だから、そのあいだに入る。中世の地中海世界では、アッコ（1173年ごろ）、バルセロナ（1221年）、マルセイユ（1228年）、パリ（1296年）の関税表に生姜が並ぶ。十四世紀なかばのイタリアの商人は、これを三つに呼び分けた。Belledi、Colombino、Micchino。三つのうち土地を指すのは Belledi（アラビア語で「土地の」「在来の」。ふつうの生姜を指す）だけで、Colombino は南インドの港クイロン＝コーラム、Micchino はメッカから、あるいはメッカ経由で来たことを示す——三つのうち二つは、運ばれてきた道の名だった。"]], "invite": "台所の生姜を、指のように分かれたところで一本折り、表面に横向きの輪（節の跡）が走っていないか探してみる。とがった芽が出ていたら、そこが次の一株になるところ——根ではなく茎だから、芽が出る。", "works": [{"t": "bun", "date": "前5〜前3世紀ごろ", "place": "中国", "title": "『論語』郷党第十", "author": "孔子とその弟子たち（編者不詳）", "quote": "不撤薑食，不多食", "src": "『論語』郷党第十（十之八）。本文は中国語版ウィキソース『論語/鄉黨第十』の全文で照合した（「沽酒市脯不食。不撤薑食，不多食。」と続く箇所）。孔子は前551〜前479年の人で、『論語』は弟子たちの記録をもとに前5〜前3世紀ごろにまとめられたとされる", "note": "「薑（きょう＝生姜）を食卓から下げなかった。ただし多くは食べなかった」。この一行は、孔子の食べ方をひとつずつ並べた長い一段の途中にある——飯は精げたものを厭わず、膾は細いのを厭わず、色の悪いものは食べず、煮えかたが悪ければ食べず、買ってきた酒と干し肉は口にしない。そのならびの終わりのほうに、薑が出てくる。暖かいアジアの草が、黄河の世界の食卓では、すでに「いつも卓にあるもの」の位置にいた。⚠️ この一行を効きめの話として説く注釈は古くからあるが、本文が書いているのは、下げなかった、それだけである。"}, {"t": "bun", "date": "1世紀（77年ごろ）", "place": "ローマ帝国（イタリア）", "title": "『博物誌』第12巻・第14章", "author": "大プリニウス", "quote": "id enim in Arabia atque Trogodytica in villis nascitur, parva herba, radice candida", "src": "『博物誌（Naturalis Historia）』第12巻・第14章（節番号では28）。ラテン語本文はラテン語版ウィキソース『Naturalis Historia/Liber XII』の全文で照合し、ペルセウス電子図書館所収のボストック＆ライリー英訳（1855年・著作権満了）の同章と突き合わせた。プリニウスは23／24〜79年の人", "note": "「それ（生姜）は、アラビアとトロゴデュティケの畑に育つ、白い根をもつ小さな草である」。トロゴデュティケ（Trogodytica）は紅海のアフリカ側の岸を指す（ラテン語本文の綴りは l の入らない Trogodytica で、Troglodytica はボストック英訳の綴り）。プリニウスはこの直前で「胡椒の木の根が生姜だという説は誤りだ」と正しく退けておきながら、産地のほうを取り違えている——ローマに届く生姜が紅海を通ってきたので、通り道を産地と読んだ。同じ章には値段もある。生姜は1ポンド6デナリウス、長胡椒15、白胡椒7、黒胡椒4。そしてもうひとつ、彼はこう書いた——「胡椒も生姜も、それぞれの国では野生に生えている」。生姜の野生は、いまだに見つかっていない。"}, {"t": "art", "f": "shouga_a1.jpg", "date": "1700年代なかば", "place": "インド・コロマンデル海岸", "title": "大判の腰布（Oversize Hip Wrapper (tapis)）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2000.28", "note": "館の解説は、この布を「オランダ東インド会社の東西の香辛料交易で、インドネシアへ輸出するためにインドで作られたもの」と説明する。スマトラ島では男女ともこれを巻き、やがて儀礼の場の布になったという。深い赤の地に小さな花の輪が隙間なく並び、両端には三角形の連なる帯（クパラ）が入る。木綿に媒染剤を描いては染め、蝋で防ぎ、また染める——1734年にフランス人ボーリュー（M. de Beaulieu）が十一の工程に分けて書き留めた手間である。大きさは296×120cm（館の記載＝高さ×幅）。香辛料は一粒も写っていない。写っているのは、香辛料と引き換えに運ばれていった側のほう。この布が渡ったのと同じ海を、生姜も渡った——ただし、そのことはこの一枚には書かれていない。"}, {"t": "art", "f": "shouga_a2.jpg", "date": "1806年（1月23日刊）", "place": "イギリス・ロンドン", "title": "ティディ・ドール、フランスの大ジンジャーブレッド職人（Tiddy-Doll, the Great French-Gingerbread-Baker; Drawing Out a New Batch of Kings, His Man Hopping Talley, Mixing Up the Dough）", "artist": "ジェームズ・ギルレイ", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/391797", "note": "手彩色のエッチング。羽根飾りの二角帽に前掛けをした男が、長い柄のへらを竈へ差し入れる。竈の上の札は「NEW-FRENCH OVEN for Imperial Gingerbread（皇帝のジンジャーブレッド用・新フランス竈）」。へらの上には金色の小さな人形が群れて立ち、その足もとに「BAVARIA」「WIRTEMB…」「BADEN」の三つの札が並ぶ。左では別の男が「Political Kneading Trough（政治のこね桶）」で生地をこね、手前の籠には「True Corsican Kinglings for Home Consumption & Exportation（本場コルシカ産の小王たち・内需用および輸出用）」。右の簞笥の引き出しは上から「Kings & Queens」「Crowns & Sceptres」「Suns & Moons」。中央の低い焚き口には「Ash-Hole for broken Gingerbread（割れたジンジャーブレッドの灰穴）」。床に落ちた巻紙には「Hot Spiced Gingerbread, all hot!」——菓子売りの呼び声である。二角帽と「コルシカ産」の札からこの職人をナポレオンと読むのは易しいが、館の記載に名前は出ていない。そして、生姜そのものは一片も描かれていない。ここにあるのは、生姜の名を負った菓子が、政治の悪口の材料になるところまで台所の言葉になっていた、という事実のほうである。"}, {"t": "art", "f": "shouga_a3.jpg", "date": "1800年代", "place": "パプアニューギニア・トロブリアンド諸島（マシム地域）", "title": "舟の波よけ板（Canoe Splashboard）", "artist": "作者不詳（マシムの彫り手）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1966.130", "note": "木を透かし彫りにした板。幅81.9cm、高さ58.7cm。上の両はしが耳のように大きく巻きこみ、面いっぱいに渦とS字が絡む。下は幅の狭い柄になって、その先に小さな突起が出ている。館の解説は「トロブリアンドの人びとはしばしば遠くまで舟で渡り、儀礼の品を交換した。手の込んだ波よけ板は、渡る者に霊的な守りを与えた」と記し、この一枚の文様を様式化されたグンカンドリだとする——渦の連なりを鳥と読むところは、館の説明にそのまま従っている。生姜は彫られていない。ここにあるのは、種で増えることのできない草が島から島へ移るのに、どうしても要ったもの——人の乗る舟の、その顔である。"}, {"t": "art", "f": "shouga_a4.jpg", "date": "1900年ごろ", "place": "スリランカ・コロンボ（当時のセイロン）", "title": "セイロン、コロンボ、街の風景（India. Ceylon. Colombo. Street Scene, after photo by Dr. Kurt Boeck）", "artist": "フォトグロブ社（チューリヒ）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2019.188", "note": "白黒写真の陰画を石版に移し、色ごとに最低六枚、多いときは十五枚の版を重ねて刷る「フォトクローム」という色刷り。館の解説にはこう書いてある——色を決めた刷り師たちは、その土地を見たことがなかった。画面では、二頭の瘤牛（こぶうし）が、編んだ大きな覆いのついた荷車を引いてこちらへ来る。右手には大きな袋が山と積まれ、その向こうにも荷車が並ぶ。袋の中身はどこにも書かれていない。下の余白に「CEYLON. COLOMBO. STREET SCENE」の刷り込み。館の年代は「c. 1890–1910」で、ここでは真ん中をとって1900年ごろとした。館の分類欄はこの一枚を「India」に入れているが、題にあるとおり写っているのはセイロン（いまのスリランカ）である。⚠️ 中世イタリアの商人が生姜の一種を Colombino と呼んだのは、この街ではなく南インドの港クイロン（コーラム）に由来するとされる。名前は似ているが、別の場所である。"}, {"t": "photo", "f": "shouga_p1.jpg", "date": "いま（2016年）", "place": "インド・タミル・ナードゥ州 イェルカード", "title": "生姜の花の穂（写真）", "author": "Yercaud-elango", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Zingiber_officinale-1-nallur-yercaud-salem-India.jpg", "note": "赤い土の上に、葉のついた細い茎が束になって立ち、その足もとから、松かさのような緑の穂が別の柄で立ち上がっている。拡大して数えると、少なくとも八つ。苞が瓦のように重なっているのが見え、白っぽい縁が一枚ずつ光る。撮影者の説明は「ショウガ科・common ginger、密な穂、淡い緑の苞、花は黄色」。この一枚では、苞のあいだから黄色い花が開いているところまでは見えない。葉の茎と花の穂が別々に立つことは、1911年の百科事典の記述とも合っている。台所で見るのは地下の部分だけなので、この草に花が咲くことを知らずにいる人は多い。"}]}, {"id": "renkon", "no": "第十五景", "kind": "yasai", "name": "蓮根", "yomi": "れんこん", "en": "Lotus root — the rhizome of the sacred lotus, Nelumbo nucifera", "rep": "renkon_a4.jpg", "lead": "泥の底を、横に走っている茎である。蓮（はす）の地下茎が、節と節のあいだで肥る。それが蓮根である。切ると穴があいているのは、地上の葉から泥の中へ空気を送る道が通っているからで、あの穴は根の跡ではなく、息の道である。", "layers": [["食べているのは、根ではない", "ハス（Nelumbo nucifera）はハス科ハス属の水生の草で、蓮根はその地下茎（根茎）が肥ったものである。根ではない。泥の底を横に走る茎で、細くくびれた節と、そのあいだの太い節間からできている。細い根も、水面へ立ちあがる葉の柄も、節から出る。食べているのは節と節のあいだ、つまり茎の胴のほうである。切り口に並ぶ穴は通気組織（つうきそしき）と呼ばれる空洞で、葉の柄の中を通る空洞とつながっている。泥の中には酸素がほとんど無いので、地上の葉から取り込んだ空気をこの管で泥の中の地下茎まで送り、別の葉から抜いていく——そういう流れがハスで報告されている。かつてハスはスイレン科に置かれたが、いまはハス科として分けられ、スイレンの近い親類ではないとされている。"], ["泥の底を、横に走る", "夏に葉と花を立て、秋の終わりに地下茎の先が肥って越冬芽になる。これが蓮根で、掘り出すのは泥をかき分ける仕事になる。日本では水圧の高いホースで泥を吹き飛ばして掘る「水掘り」が広く行われ、収穫量がいちばん多いのは茨城とされる（霞ヶ浦のまわりに蓮田が広がる）。表面に残る赤錆色の筋や斑は、泥の中の鉄分による染みとされる。ハス属は世界に二種しかない。アジアからオーストラリア北部にかけてのハスと、北アメリカのキバナハス（N. lutea）である。なおエジプトの壁画やギリシャ・ローマの器に出てくる「ロータス」は、ふつうスイレン属（Nymphaea）の別の植物で、蓮根はできない。名前だけが、別の属へ渡っている。実は硬く、長もちする。1951年に千葉市検見川の泥炭層から掘り出された実の一粒が翌年に花を開き、大賀ハスと呼ばれている——実はおよそ二千年前のものと推定されている（推定には幅がある）。"], ["葉は、濡れない", "蓮の葉に水をかけても濡れない。水は玉になって残り、少し傾けただけで転がり落ちる。葉の表面に十マイクロメートルほどの細かい突起がびっしり並び、その上をロウの結晶が覆っているためで、水は突起の先にしか触れられず、玉のまま浮いている。転がるときに埃を巻き取っていくので、葉は自分で清くなる。この仕組みは1990年代にドイツ・ボン大学のバルトロットらが電子顕微鏡で調べ、〈ロータス効果〉と名づけた。汚れのつかない塗料や布の手本にされている。古い詩は、この一点をよく見ていた。『バガヴァッド・ギーター』は「蓮の葉が水に濡れないように」と言い、『古今和歌集』の僧正遍昭は、蓮の葉にたまった露が玉に見えることを詠んだ。ただし濡れないのは表面の作りのことで、泥に染まらないという徳の話とは、本当は別のことである。"]], "invite": "蓮根を、切り口ではなく外側から見てみる。細くくびれて色の濃い帯（節）を探す。ふくらみが二つつながっていれば、そのつなぎ目に。一節に切られていれば、端に黒っぽい輪として残っていることが多い。細い根も、折れた柄の跡も、その帯からだけ出ていて、ふくらみの胴には出ていない。食べているのは節と節のあいだ——泥の中を横に走っていた茎である。", "works": [{"t": "bun", "date": "前5〜後2世紀ごろ", "place": "南アジア（サンスクリット語）", "title": "『バガヴァッド・ギーター』第五章一〇", "author": "作者不詳（『マハーバーラタ』の一部）", "quote": "lipyate na sa pāpena padmapatram ivāmbhasā", "src": "『バガヴァッド・ギーター』5.10 の後半。ローマ字転写は、保護期間の満了した刊本、A. W. シュレーゲル（1767〜1845）校訂『Bhagavad-Gita, id est Thespesion melos』（ボン、Eduard Weber、1823年）第五章（Lectio V）28頁の第10詩節（लिप्यते न स पापेन पद्मपत्रमिवाम्भसा）で一字ずつ照合した（Internet Archive のスキャン <https://archive.org/details/bhagavadgitaide00schlgoog>。異同なし）。サンスクリット語版ウィキソース「भगवद्गीता/कर्मसंन्यासयोगः」の同章一〇と、ゲッティンゲン大学の電子テキスト集 GRETIL のシャンカラ註本（sa_bhagavadgItA-comm・参照番号 bhg_5.10。CC BY-NC-SA 4.0）とも突き合わせた。成立年代に定説はない", "note": "「ブラフマンに行いを預け、執着を捨てて行う者は、罪に染まらない——蓮の葉が水に濡れないように」。二千年ちかく前の詩が、蓮の葉が濡れないことを、たとえの土台としてすでに当たり前に使っている。ivāmbhasā は「水によって〜のように」で、シャンカラの註はここを「水によって（udakena）」と言い換える（ambhas も udaka も「水」で、滴とは言っていない）。葉に水が乗っても、葉の側に何も残らない、という観察である。同じ見立ては東アジアにも別に育っていて、『古今和歌集』の僧正遍昭の歌は《つち百景》の〈泥〉に引いてある。"}, {"t": "art", "f": "renkon_a1.jpg", "date": "8世紀後半〜10世紀後半", "place": "インドネシア・ジャワ島", "title": "蓮（Lotus (Pripih)）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/49700", "note": "館の記載＝金、中部ジャワ期、インドネシアの金製品を集めた一括寄贈のうちの一点。薄い金の板を先のとがった花弁の形に切り、放射状に開いて二重ほどに重ねてある（重なっていて枚数は決められない）。中心では細く切った金の帯が幾筋も巻き上がって絡まりあう——花の中心の蕊（しべ）をここに読むのはこちら側で、館は形の説明をしていない。表面には青緑の細かい点が散る（館の記す材は金で、この点が何かは書かれていない）。館は題に (Pripih) と添えるだけで、それが何を指すかは書いていない。寸法は「高さ27cm・径7.3cm」と記されるが、写真の平たく開いた姿と結びつけにくく、館の記載のまま写した。"}, {"t": "bun", "date": "1063年", "place": "中国（北宋）", "title": "『愛蓮説』", "author": "周敦頤", "quote": "予獨愛蓮之出淤泥而不染，濯清漣而不妖，中通外直，不蔓不枝", "src": "中国語版ウィキソース「愛蓮說」（書誌は北宋・1063年、底本を『周元公集』および『古文評註』とする）で本文照合。同ページに付された『古文評註』の注は「中通外直」を「其莖中玲瓏相通而不礙，其外則直幹森森而不曲」と説く", "note": "「わたしはただ、蓮が泥の中から出て染まらず、清らかなさざなみに洗われて艶かしくなく、中は通って外は直く、蔓を這わせず枝を分けないのを愛する」。よく引かれるのは前半の「淤泥（おでい）より出でて染まらず」のほうで、そちらは《つち百景》の〈泥〉に引いた。ここで見たいのは次の四字、中通外直である。同ページの『古文評註』の注は、これを「茎の中は玲瓏として通り、外はまっすぐで曲がらない」と説く。十一世紀の中国では、蓮の茎が中空であることが、すでに徳のたとえの土台になっていた。穴のほうが、先に見られている。"}, {"t": "art", "f": "renkon_a2.jpg", "date": "12世紀ごろ", "place": "カンボジアまたはタイ", "title": "蓮の花の形の飾り（Ornament in the Shape of a Lotus Flower）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/37783", "note": "館の記載＝青銅、鍍金の跡あり、高さ7インチ（17.8cm）。産地は「カンボジアまたはタイ」と二つ並べて書かれる（館自身が一つに決めていない）。厚い金属の花弁が幾重にも開き、その中央に円盤が据わる。5倍に拡げて数えると、円盤の上には中央の大きな粒を八つの粒がぐるりと囲み、円盤の縁は小さな球の連なりで飾られている。この円盤を蓮の花托——花の中心にあって実を抱く、穴の並んだあの台——と読むのはこちら側で、館の記載は「蓮の花の形の飾り」とだけ言う。花弁は割れ、欠け、青緑の錆が出ている。中央の一つを八つが囲むという並びは、蓮根の切り口の穴の並びを思わせる——が、それはこちら側の見立てである。"}, {"t": "art", "f": "renkon_a3.jpg", "date": "1300年ごろ", "place": "中国（元）", "title": "蓮と水鳥（Lotus and waterbirds）── 対幅", "artist": "作者不詳（元・佚名）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/36437", "note": "館の記載＝絹本着色の掛軸二幅、元代。画面は一幅141.6×67.9cm、表装まで入れると273.1cm になる。写真は表装ごと二幅を並べて写している。太い緑の茎が水面からまっすぐ立ち、その先に紅の花、開ききった花、まだ堅い蕾がつく。大きな葉は縁が波打ち、水に浮くものと立ち上がるものとがある。3倍に拡げると、右幅の上のほうに淡い斑を散らした緑の円盤が一つ見える——花の散ったあとの花托である。左幅の水面には二羽の水鳥が浮かび、右幅には白い鳥が二羽立つ。画面の下は暗く沈んでいて、泥は描かれない。茎の下がどうなっているかは、この絵からは見えない。"}, {"t": "art", "f": "renkon_a4.jpg", "date": "1845〜54年ごろ", "place": "日本（江戸）", "title": "蓮根とアダーズ・タング（Lotus Root and Adder's Tongue）", "artist": "椿椿山（1801〜1854）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1985.293", "note": "館の記載＝紙に水彩（watercolor on paper）、素描の部、紙寸28×34.4cm。二節つながった蓮根が斜めに横たわり、左下の切り口がこちらを向く。4倍に拡げて数えると、その切り口には穴が八つ——中央の一つを、大小の穴が囲んでいる。切り口の輪郭は円ではなく、いくつも張り出した波形をしている。二つの節のつなぎ目には黒く鋭い線が四方へ散る。青緑のとがった葉が立ちあがるのはそこではなく、少し右へ寄った胴の上からで、ハスの円い盾形の葉とは形が違う。この葉がどちらの草のものかは決めない。右のほうには、濃い斑を鱗のように並べた球形のものが三つ並び、そのひとつの頂からは橙のとがった形が二本立ちあがる。左上に四字の款記と朱文の方印。当方の読みでは「冰廚清供」と見えるが、館に翻刻は無い（館の記録は款記を「右下隅」と書くけれども、右下は白紙である）。館の題は蓮根のほかに Adder's Tongue をもう一種数えるが、この英名はハナヤスリの類にもカタクリの類にも使われ、どれかはこの一枚からは決められない。日本語の定訳が無いので題は音のまま写した。"}, {"t": "photo", "f": "renkon_p1.jpg", "date": "いま（2014年）", "place": "ベトナム南部", "title": "ベトナム南部の蓮根 củ sen（写真）", "author": "Bùi Thụy Đào Nguyên", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File:C%E1%BB%A7_sen.jpg", "note": "撮影者の説明はベトナム語で「Củ sen ở miền Nam Việt Nam」（ベトナム南部の蓮根）。淡い緑の台の上に、洗ったばかりの蓮根が二十ばかり積み上げてある（重なっていて正確には数えられない）。ふくらみが二つつながったままのものが混じっていて、そのあいだが細くくびれる。7倍に拡げると、くびれの帯から茶褐色の細い根が房になって出ており、黒く縮んだ短い突起——折れた柄のように見えるもの——も同じ帯から立っている。ふくらみの表面には縦に走る繊維の筋と、赤錆色の細かい斑がある。切り口は写っていないので、穴はこの一枚では見えない。泥から上がったばかりの、まだ切られていない茎である。"}]}, {"id": "kansho", "no": "第十六景", "kind": "yasai", "name": "砂糖黍", "yomi": "さとうきび", "en": "Sugarcane — Saccharum officinarum, the giant grass that stores sugar in its stem", "rep": "kansho_a3.jpg", "lead": "茎に砂糖をためこむ、人の背を越す大きな草である。出どころはニューギニアのあたりとされ、東南アジアの海を経てインドへ渡り、そこで結晶になった。その結晶を指すサンスクリットの語（śarkarā）が、めぐりめぐって英語の sugar になっている。そしてこの草の甘さは、大西洋を渡る奴隷貿易のおもな土台のひとつになった。", "layers": [["砂糖は、茎の中にたまっている", "イネ科サトウキビ属の多年草。和名はサトウキビ（砂糖黍）、別名を甘蔗（かんしゃ・かんしょ）といい、沖縄方言ではウージ、種子島ではおうぎ、徳之島ではうぎと呼ぶ。茎は高さ三メートルにもなり（品種と土地によって二〜七メートルとされる）、稲や麦と同じ仲間でありながら、実ではなく茎に糖をためる。熟した茎のうちわけは、およそ水分 63〜73%、溶けている糖分 12〜16%、繊維 11〜16% とされる——つまり、重さのうち一割から二割ほどが繊維で、残りはしぼれば汁になる。強い日ざしと高い温度で効率よく炭素を固定する C4 型の光合成をおこなう植物で、収穫量でみると世界でいちばん多く穫れる作物である（2022年で約19億トン、ブラジル 38%・インド 23%・中国 5%）。世界の砂糖の 79% はこの草から来ており、残りの多くはテンサイ（ビート）から来る。種でも殖えるが、ふつうは茎を節ごとに切って土に埋める。節にはひとつずつ芽があり、そこから新しい株が立つ。刈ったあとの株からもまた芽が出る（株出し）ので、一度植えれば二回から十回ほど穫れる。"], ["ニューギニアから、東と西へ", "栽培されるサトウキビ（Saccharum officinarum）は、ニューギニアで栽培化されたとされる。およそ 6000 年前から、その地に自生する Saccharum robustum の系統が選び分けられていった、というのが現在の説明である。そこから西へ、島づたいに東南アジアへ渡り、途中で別の野生種 Saccharum spontaneum と交雑した。オーストロネシア語族の交易の手を経て、3000 年前ごろには中国とインドに届いていたという。インドでこの汁は結晶になった。サンスクリットの śarkarā（砂糖の粒）が、アラビア語・ラテン語をへて英語の sugar になる。中国では、唐の太宗のときに西方から精糖の技術が伝わったと書かれる。日本へは、砂糖は奈良時代に鑑真が伝えたとされ、江戸期には高松藩が和三盆をつくり出した。草そのものは東（ニューギニア）から西へ渡り、それを結晶にする技術と名前は、そのあと西（インド）から東へ戻ってきている。"], ["甘さの、代価のほう", "この草がヨーロッパの手に渡ったとき、砂糖はまず薬であり、次に贅沢品になり、やがて日々のものになった。栽培に適したカリブ海と南アメリカが植民地にされ、そこに開かれた農園で、奴隷にされた多数の人びとにサトウキビを作らせた。製糖農園での労働は、大西洋を渡る奴隷貿易のおもな土台のひとつになった、と説明される。キューバへ奴隷として連れてこられたアフリカの人びとは百万人を超えるとも言われる（推計には幅がある）。19世紀に奴隷貿易への圧力が強まると、こんどは十万人を超えるとされる中国人年季労働者が入れられた。スペインがキューバの奴隷制を廃したのは 1886 年で、西半球でもっとも遅い部類にあたる。この景に並ぶ 1857 年のキューバの石版画と、1853 年のルイジアナの手記は、同じ十年ほどのあいだの、同じ作物の、持ち主の側から見た姿と、刈る側から見た姿である。"]], "invite": "台所か、スーパーの砂糖の棚で、袋の裏の原材料名だけを読み比べてみる。黒糖には「さとうきび」の一語しか書いていないもの（純黒糖＝しぼり汁を煮つめて冷やしただけのもの）と、そこに「粗糖」「糖みつ」が並ぶもの（加工黒糖）がある。てんさい糖には「てん菜」と書いてある。ところが上白糖やグラニュー糖の欄は「原料糖」とだけ書かれていることが多く、その甘さがどの植物の茎から来たのかは、そこには書かれていない。", "works": [{"t": "bun", "date": "前1200〜前1000年ごろ", "place": "インド北西部（『アタルヴァ・ヴェーダ』シャウナカ本）", "title": "『アタルヴァ・ヴェーダ』第一巻 三四歌 第五詩節", "author": "作者不詳（アタルヴァン系の讃歌）", "quote": "pári tvā paritatnúnekṣúṇāgām ávidviṣe | yáthā mā́ṃ kāmíny áso yáthā mán nā́pagā ásaḥ", "src": "『アタルヴァ・ヴェーダ』シャウナカ本 1.34.5。サンスクリット本文はアクセント記号まで、保護期間の満了した刊本、R. ロート（1821〜1895）／W. D. ホイットニー校訂『Atharva Veda Sanhita』第一巻・本文（ベルリン、Ferd. Dümmler、1856年）13頁の第34歌第5詩節で一字ずつ照合した（Internet Archive のスキャン <https://archive.org/details/india.history.resource.70884>）。この刊本は第三句を कामिन्यसो（kāmíny áso・長い ā）と刷っており、同じ句をくり返す 2.30.1 とも揃うので、引用もそれに合わせた。GRETIL（ゲッティンゲン大の電子テキスト集）の「Atharvaveda-Samhita, Saunaka recension, accented text」（AVŚ_1,34.5a／1,34.5c。CC BY-NC-SA 4.0）とも突き合わせたが、そちらは 1.34.5 だけ kamíny（短い a）となっている。英訳はホイットニー訳（W. D. Whitney／1827〜1894・著作権満了）『Atharva-Veda Samhita』Book I, Hymn 34 を英語版ウィキソースで照合した", "note": "愛のまじないの歌である。ホイットニーは表題を「甘い草をもちいた愛の呪」と付ける。第一詩節が「蜜から生まれた草」（マドゥガ＝甘い草）を掘るところから始まり、第二〜四詩節は蜜の語で埋まる。ikṣu＝甘蔗が出てくるのは第五詩節だけである。「巻きつく甘蔗で、わたしはあなたのまわりをめぐった、憎み合わずにいるために。あなたがわたしを慕う人であるように、わたしのもとを去らぬように」（訳は当方）。ホイットニーは encompassing sugar-cane と訳している。甘さで人をつなぎとめるという考え方が、この草の名とともに、はやくから文字になっている。ヴェーダの成立年代には幅があるので、ここでは前1200〜前1000年ごろ「とされる」にとどめた。"}, {"t": "art", "f": "kansho_a1.jpg", "date": "14世紀", "place": "日本（南北朝期）", "title": "糖 ── 砂糖をうたった漢詩（Poem in Chinese about Sugar）", "artist": "虎関師錬（Kokan Shiren／1278〜1346）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/42693", "note": "館の記載＝南北朝期、紙本墨書の掛軸、本紙 31.1 × 47.3 cm。題は「砂糖についての漢詩」。金襴の表具に囲まれた横長の紙に、行書が五行。当方が画面から読めたかぎりでは〈謾教水火起争端／百煉千熬只自安／滋味莫言都似蜜／舌頭回轉又酸寒〉の七言絶句で、いちばん左に本文より小さく「糖」の一字、その下に朱の印が捺してある。水と火が争い、百度ねり千度煮つめてようやく落ちつく、味は蜜のようだと言うな、舌の上で転がせばまた酸くて寒い——製糖の手つきがそのまま修行の比喩に読めるが、そう読むのはこちら側である。行書のくずしなので判読は当方のもので、詩集『済北集』の本文には当たれていない。虎関師錬は臨済宗の僧、『元亨釈書』の著者。"}, {"t": "bun", "date": "1853年", "place": "アメリカ合衆国・ルイジアナ州（バイユー・ブフ）", "title": "『十二年の奴隷（Twelve Years a Slave）』第十五章", "author": "ソロモン・ノーサップ", "quote": "He received for my services a dollar a day, with the money supplying my place on his cotton plantation. Cutting cane was an employment that suited me, and for three successive years I held the lead row at Hawkins', leading a gang of from fifty to an hundred hands.", "src": "Solomon Northup『Twelve Years a Slave』(Auburn: Derby and Miller, 1853) 第十五章。本文は二重照合＝①プロジェクト・グーテンベルクの電子テキスト（eBook #45631）②英語版ウィキソース「Twelve Years a Slave/Chapter 15」（1853年版のスキャンからの翻刻）。章題も両者一致（LABORS ON SUGAR PLANTATIONS—THE MODE OF PLANTING CANE…）", "note": "自由な市民として生まれ、誘拐されて十二年を奴隷として過ごした人の手記。「綿摘みが不得手だったので、エップスは刈り入れと製糖の季節、わたしを製糖農園へ貸し出す習いだった。彼はわたしの働きに対して日に一ドルを受け取り、その金で綿畑のわたしの穴を埋めた。甘蔗を刈るのは性に合う仕事で、三年つづけてホーキンズの畑で先頭の列を持ち、五十人から百人の組を率いた」。働いたのは本人、金は主人が取る。同じ章は作り方も細かく書く——茎の節にはじゃがいもの芽のような芽（eye）がひとつずつあり、埋めれば芽を出す。刈るナイフは刃渡り十五インチ、中ほどで幅三インチ（先と柄へ向かって細くなる）。植物学の本と同じことが、刈る側の手から書かれている。", "care": "奴隷制の記述"}, {"t": "art", "f": "kansho_a2.jpg", "date": "1857年", "place": "キューバ・ハバナ（描かれたのはカルデナス管区グアムタス地区の製糖所）", "title": "製糖所〈フロール・デ・クーバ〉（Ingenio Flor de Cuba）──『ロス・インヘニオス』", "artist": "エドゥアルド・ラプランテ（1818〜1886・写生および石版）／フスト・ヘルマン・カンテーロ（1815年生・本文）", "museum": "Wikimedia Commons（ハバナ・L・マルキエ石版所の版）", "lic": "CC0", "url": "https://commons.wikimedia.org/wiki/File:Ingenio_Flor_de_Cuba_1857.jpg", "note": "手彩色の石版。白い高い煙突が二本立ち、黒い煙が斜めにたなびく（右手にもう一本、低い煙突も煙を上げる）。その下にアーチを並べた大きな建屋、手前には細長い平屋が横たわって、小さな戸口が等間隔に並び、柵ぎわに四つ足の家畜が何頭も休んでいる（この平屋が何かは記載にない）。右手には望楼をのせた白い母屋。並木の道を荷車が数珠つなぎに登ってきて、馬に乗った人が横切る。いちばん手前は石積みの土手道と水で、白い水鳥が三羽、幌をかけた二輪馬車が一台。Commons のスペイン語の説明は「製糖所フロール・デ・クーバ。アリエタ家の所有。西部県カルデナス管区グアムタス地区」。この製糖所の持ち主はアリエタ家で、本文を書いたカンテーロは別の製糖所の持ち主である。大きく描かれているのは建物と煙突で、人は米粒ほどしかない。"}, {"t": "art", "f": "kansho_a3.jpg", "date": "1877〜83年", "place": "フィリピン・マニラ（図版の石版刷りはバルセロナ）", "title": "サトウキビ 紅色矮性変種（SACCHARUM OFFICINARUM VAR. RUBRUM HUMILE）──『フィリピン植物誌』大版 図18", "artist": "作者不詳（Commons の作者欄は本の著者フランシスコ・マヌエル・ブランコの名を挙げる）", "museum": "Wikimedia Commons（スペイン王立植物園のスキャン）", "lic": "パブリックドメイン", "url": "https://commons.wikimedia.org/wiki/File:Saccharum_officinarum_Blanco1.18.jpg", "note": "多色石版。右上に図番号「18」、下に「SACCHARUM OFFICINARUM.—LINN.—Blanco. VAR. RUBRUM HUMILE.—MIQ.—Hassk.」、右下に小さく「Lit. C. Verdaguer, Barcelona」と刷ってある。株の下半分は葉鞘に包まれ、それを剥いたところに暗紅色の節間と、淡い緑の節の輪が二つのぞく——茎に糖がたまるのはこの節と節のあいだである。葉は長く反り返り、下のほうは枯れて垂れる。右側には穂だけを切り離して描いた図があり、細かく枝分かれした円錐花序が房になって垂れている。左には花序の枝を一本だけ、色をつけず淡い線で描いた小図。Commons はこの画像を「清掃・色調整・回転」を施した修整版と明記しているので、色は原本そのままではない。"}, {"t": "art", "f": "kansho_a4.jpg", "date": "1969年", "place": "パプアニューギニア・西部高地（上カウゲル）", "title": "サッカルム・ロブストゥム（Saccharum robustum）の押し葉標本 ── 合衆国国立植物標本館 3332582", "artist": "採集：N・バウアーズ（Bowers 575）／標本写真：スミソニアン国立自然史博物館 植物部門", "museum": "スミソニアン国立自然史博物館 合衆国国立植物標本館（Wikimedia Commons 経由）", "lic": "CC0", "url": "https://commons.wikimedia.org/wiki/File:Saccharum_robustum.jpg", "note": "台紙に六本ほどの茎と葉が白い紐で留めてある。葉鞘に包まれた茎、剥けたところの節、右上に赤茶けた穂。左上には種子を入れる折り紙の袋。右下のラベルは活字で「パプア・ニューギニア領／森林局」と刷られ、タイプ打ちでこう埋めてある——採集者バウアーズ 575／イネ科／学名 Saccharum robustum／産地アリペ・マニャ、ケパカ、上カウゲル／ハーゲン郡、西部高地県／標高 7600 フィート／1969年1月20日／生育のようす「便所の目隠しとして植えられていた」／高さ 18 フィート／花は暗赤色／土地の名「コロ」。栽培のサトウキビが選び分けられてきた野生の親類とされる草が、その故郷の高地で、目隠しとして立っていた。"}, {"t": "photo", "f": "kansho_p1.jpg", "date": "いま（2010年）", "place": "インドネシア・東ジャワ（マラン県ゴンダンレギ）", "title": "甘蔗畑のあいだの道（写真）", "author": "snrtindar", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File:Kebun_tebu_reco_banteng,_gondang_legi_-_panoramio.jpg", "note": "砂利まじりの細い道が、二枚の畑にはさまれて奥へ伸びている。左の株は背が高く、暗い赤紫の茎に節の輪が見え、それが何本も斜めに立ち上がって、上で長い葉が弓なりに垂れ、道の上まで張り出している。右の株はまだ低く、日を受けて明るい。道の縁には草。奥に椰子の木立と、枝を広げた大きな木、青い空に白い雲。撮影者の説明はインドネシア語で「レチョ・バンテン、ゴンダンレギの甘蔗畑（kebun tebu）」とだけあり、それ以上は書かれていない。ファイルには座標が付いていて、東ジャワ・マラン県ゴンダンレギを指す。人の背より高い草のあいだを、人ひとり分の道が抜けていく。"}]}];